ns.Locale("frFR", function(L)
	L["binding.birch.description"] = "Pâle et fine comme du papier, aux mouchetures sombres. Sans doute le seul livre ici qui flotterait."
	L["binding.birch.name"] = "Écorce de bouleau"
	L["binding.bone.description"] = "Du cuir brut tendu sur un cadre, fermé par deux boutons d’os sculptés. Craque dans le froid."
	L["binding.bone.name"] = "Os et cuir brut"
	L["binding.brasscase.description"] = "Un étui de laiton gravé d’un poisson bondissant au-dessus des roseaux, avec un loquet qui claque comme s’il le pensait."
	L["binding.brasscase.name"] = "Étui de chasse en laiton"
	L["binding.buckram.description"] = "Une toile raide vert d’eau aux filets crème. Les embruns perlent et roulent aussitôt."
	L["binding.buckram.name"] = "Bougran vert d’eau"
	L["binding.canvas.description"] = "Une simple toile kaki, marquée au pochoir d’un numéro que personne ne se souvient d’avoir attribué. Tient dans une poche de manteau, tout juste."
	L["binding.canvas.name"] = "Carnet de terrain en toile"
	L["binding.chartlinen.description"] = "Un lin pâle imprimé d’une vieille carte, ses lignes de profondeur adoucies aux coins par quelques saisons de pouces."
	L["binding.chartlinen.name"] = "Lin à carte des marées"
	L["binding.copper.description"] = "Des plaques de cuivre rivetées sur des planches, verdies aux jointures. Bruyant à fermer, impossible à cabosser."
	L["binding.copper.name"] = "Cuivre riveté"
	L["binding.coral.description"] = "Des branches de corail rouge serties dans un cuir vert d’eau, avec des perles au bout des branches."
	L["binding.coral.name"] = "Incrustation de corail"
	L["binding.driftwood.description"] = "Trois planches de bois flotté gris, clouées à un dos de cuir. Lourd, honnête et légèrement salé."
	L["binding.driftwood.name"] = "Planches de bois flotté"
	L["binding.eelskin.description"] = "Des bandes de peau d’anguille cousues côte à côte, sombres et lisses, avec un éclat qui bouge avec la lumière."
	L["binding.eelskin.name"] = "Peau d’anguille"
	L["binding.field.description"] = "Un simple cuir brun, fait pour prendre la pluie, ce qu’il fait d’ordinaire."
	L["binding.field.name"] = "Cuir de terrain"
	L["binding.frosthide.description"] = "Une peau tannée dans le froid jusqu’à blanchir, bordée de fourrure le long du dos pour les mains sans gants."
	L["binding.frosthide.name"] = "Peau tannée au gel"
	L["binding.kodo.description"] = "Une épaisse peau des plaines, le poil usé par endroits, lacée de cuir brut. Elle survivra au pêcheur."
	L["binding.kodo.name"] = "Peau de kodo"
	L["binding.kraft.description"] = "Du papier brun frotté à la cire d’abeille jusqu’à ce que la pluie glisse dessus. Noué de ficelle, parce que les boutons tombent."
	L["binding.kraft.name"] = "Kraft ciré"
	L["binding.lacquer.description"] = "Couche après couche de laque rouge, polie jusqu’à refléter, avec une carpe dorée qui y nage."
	L["binding.lacquer.name"] = "Laque rouge"
	L["binding.maplinen.description"] = "Une carte dessinée à la main sur du lin, le sentier en pointillés rouges et une croix là où quelqu’un jure que vit le gros."
	L["binding.maplinen.name"] = "Carte sur lin"
	L["binding.morocco.description"] = "Du chevreau rouge entièrement orné d’un treillis d’or, le genre de reliure qu’on garde d’ordinaire derrière une vitre."
	L["binding.morocco.name"] = "Maroquin doré"
	L["binding.moss.description"] = "Un cuir resté trop longtemps sur une berge humide. La mousse a pris, et le livre semble s’en porter mieux."
	L["binding.moss.name"] = "Moussue"
	L["binding.netcork.description"] = "Des plats de liège sous un filet noué, avec un flotteur attaché. Il ne coulera pas, ce que peu de livres peuvent dire."
	L["binding.netcork.name"] = "Filet sur liège"
	L["binding.oilskin.description"] = "Une toile cirée jaune qui laisse filer pluie et embruns. On la retrouve au fond de la barque, et c’est bien le but."
	L["binding.oilskin.name"] = "Ciré jaune"
	L["binding.pearl.description"] = "Une couverture de coquillage, taillée pièce par pièce et ajustée comme des carreaux. Elle change de couleur chaque fois qu’on tourne le livre."
	L["binding.pearl.name"] = "Nacre"
	L["binding.planks.description"] = "De fines planches sanglées de cuir et de boucles de laiton. Sert de planche à découper au besoin."
	L["binding.planks.name"] = "Planches sanglées"
	L["binding.sailcloth.description"] = "Une vieille voile, goudronnée de noir contre les intempéries et surliée de ficelle sur les bords."
	L["binding.sailcloth.name"] = "Toile à voile goudronnée"
	L["binding.scrimshaw.description"] = "Un vieux panneau d’ivoire gravé d’un navire et d’un poisson par un marin au long voyage et au couteau aiguisé."
	L["binding.scrimshaw.name"] = "Ivoire gravé"
	L["binding.shagreen.description"] = "Une peau de raie, grenue comme le givre, avec l’étoile pâle au centre que gardaient toujours les anciens artisans."
	L["binding.shagreen.name"] = "Galuchat de raie"
	L["binding.shagreenbone.description"] = "Du galuchat vert, chaque grain compris, avec de l’os incrusté comme un lever de soleil. Fait pour un capitaine qui voulait des livres assortis à son salon."
	L["binding.shagreenbone.name"] = "Galuchat et os"
	L["binding.sharkskin.description"] = "Une peau grise et rugueuse aux fers d’argent. Elle ne glisse pas d’une main mouillée."
	L["binding.sharkskin.name"] = "Peau de requin"
	L["binding.snakeskin.description"] = "La peau d’un long serpent des marais, encore marquée des losanges avec lesquels il chassait. Fraîche au toucher, toujours."
	L["binding.snakeskin.name"] = "Peau de serpent"
	L["binding.tartan.description"] = "Une épaisse laine vert et marine traversée d’une ligne rouge. Mains au chaud, pages humides, aucun regret."
	L["binding.tartan.name"] = "Laine écossaise"
	L["binding.tooled.description"] = "Un cuir sombre repoussé de roseaux et de poissons bondissants, par quelqu’un qui avait un couteau aiguisé et un long hiver."
	L["binding.tooled.name"] = "Cuir repoussé"
	L["binding.trophycase.description"] = "Un étui de bois sombre à façade vitrée, et derrière la vitre un poisson coulé dans l’or. S’ouvre comme une armoire."
	L["binding.trophycase.name"] = "Vitrine à trophée dorée"
	L["binding.turtle.description"] = "Des plaques d’écaille polies, ambre et fumée, serties dans un cadre sombre. Plus vieilles que le livre, et sans doute appelées à lui survivre."
	L["binding.turtle.name"] = "Écaille de tortue"
	L["binding.velvet.description"] = "Un velours bleu nuit brodé d’étoiles d’argent et d’une lune. À lire à la lanterne, ce qui est justement le moment où on le lit."
	L["binding.velvet.name"] = "Velours de nuit"
	L["binding.verdigris.description"] = "Des coins de cuivre et un fermoir de cuivre, verdis par l’air marin. Ils ont été brillants, un temps."
	L["binding.verdigris.name"] = "Vert-de-gris"
	L["good.core.crate.description"] = "Emballées sur les quais par quelqu’un qui ne dit jamais ce qu’il y a dedans. Presque chaque caisse contient une apparence que vous n’avez pas encore, d’autant plus rare qu’on creuse profond. De la paille, surtout."
	L["good.core.crate.name"] = "Caisse de curiosités"
	L["good.core.crest.fish.12238.description"] = "Un large mérou gris sur la mer grise dont il porte le nom, la gueule ouverte comme toujours."
	L["good.core.crest.fish.12238.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13422.description"] = "Une anguille aux écailles de pierre enroulée sur l’eau bleue. Les armuriers convoitent l’écu."
	L["good.core.crest.fish.13422.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13754.description"] = "Un lourd poisson bleu en haute mer, bâti comme un poing."
	L["good.core.crest.fish.13754.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13755.description"] = "Un calmar pâle sur un bleu de glace hivernal, chaque bras enfin démêlé."
	L["good.core.crest.fish.13755.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13756.description"] = "Une perche sur un vert de lac, la gueule assez grande pour toute la saison."
	L["good.core.crest.fish.13756.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13757.description"] = "Une anguille en travers d’un champ d’orage, des étincelles encore sur les bords."
	L["good.core.crest.fish.13757.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13758.description"] = "Un rouget rayé sur un champ rouge braise. Les ouïes sont ce qu’il a de plus vif."
	L["good.core.crest.fish.13758.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13759.description"] = "Un lutjan violet sur l’eau de nuit. Gagné dans le noir, surtout."
	L["good.core.crest.fish.13759.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13760.description"] = "Un saumon pailleté d’or qui monte dans l’eau verte, accrochant chaque heure de lumière."
	L["good.core.crest.fish.13760.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13888.description"] = "Un homard sur fond bleu, pinces en avant, comme il y tient."
	L["good.core.crest.fish.13888.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13889.description"] = "Un saumon pâle comme le givre sur un bleu froid. Toutes ses couleurs, prises avant qu’il fonde."
	L["good.core.crest.fish.13889.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13890.description"] = "Un poisson aux plaques osseuses sur un bleu de glace, son armure enfin surclassée."
	L["good.core.crest.fish.13890.name"] = "Blason : {fish}"
	L["good.core.crest.fish.13893.description"] = "Le grand cousin sur un champ de mer profonde. Il a fallu les deux mains, et un ami, bien des fois."
	L["good.core.crest.fish.13893.name"] = "Blason : {fish}"
	L["good.core.crest.fish.1467.description"] = "Un poisson-lune sur un vert de lac. Pour le pêcheur qui a vu toutes les taches qu’il peut porter."
	L["good.core.crest.fish.1467.name"] = "Blason : {fish}"
	L["good.core.crest.fish.16967.description"] = "Un thon aux nageoires jaunes sur un vert de rivière, les longues nageoires rabattues comme des bannières."
	L["good.core.crest.fish.16967.name"] = "Blason : {fish}"
	L["good.core.crest.fish.16968.description"] = "Un chasseur rayé qui traverse l’eau bleue, dents en avant."
	L["good.core.crest.fish.16968.name"] = "Blason : {fish}"
	L["good.core.crest.fish.16969.description"] = "Un voilier sur le vert-bleu de la côte de la jungle, voile levée pour le public."
	L["good.core.crest.fish.16969.name"] = "Blason : {fish}"
	L["good.core.crest.fish.16970.description"] = "Une coryphène verte et or sur la côte de la jungle, éclatante comme au jour de sa prise."
	L["good.core.crest.fish.16970.name"] = "Blason : {fish}"
	L["good.core.crest.fish.19807.description"] = "Un poisson tacheté sur la côte du concours. Toutes ses variétés, tous les concours."
	L["good.core.crest.fish.19807.name"] = "Blason : {fish}"
	L["good.core.crest.fish.19975.description"] = "Un poisson brun et trapu sur une eau trouble. L’écu, par bonheur, ne sent rien."
	L["good.core.crest.fish.19975.name"] = "Blason : {fish}"
	L["good.core.crest.fish.21071.description"] = "Un petit poisson, sa haute nageoire dressée, sur le vert d’un ruisseau de colline."
	L["good.core.crest.fish.21071.name"] = "Blason : {fish}"
	L["good.core.crest.fish.21153.description"] = "L’aînée de son espèce, devenue vieille et majestueuse, sa nageoire en bannière sur l’eau verte."
	L["good.core.crest.fish.21153.name"] = "Blason : {fish}"
	L["good.core.crest.fish.251524.description"] = "Un poisson doré qui traîne une soie bleue sur l’eau verte. Personne ne sait toujours comment il est arrivé là."
	L["good.core.crest.fish.251524.name"] = "Blason : {fish}"
	L["good.core.crest.fish.4603.description"] = "Un jaune-queue qui monte dans l’eau bleue, la queue la première, à tous égards."
	L["good.core.crest.fish.4603.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6289.description"] = "Un lutjan tout en mâchoire sur un vert d’étang. Gagné une morsure à la fois."
	L["good.core.crest.fish.6289.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6291.description"] = "Le plus petit poisson de tous les écus, et le plus difficile à arrêter de pêcher."
	L["good.core.crest.fish.6291.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6299.description"] = "Un triste poisson gris sur une eau sombre. Il fallait bien que quelqu’un les collectionne tous. C’était vous."
	L["good.core.crest.fish.6299.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6303.description"] = "Un maquereau rayé en haute mer, qui glisse hors du cadre comme d’habitude."
	L["good.core.crest.fish.6303.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6308.description"] = "Moustaches, rancune et vert de rivière. Chacun d’entre eux a boudé au bout de votre ligne."
	L["good.core.crest.fish.6308.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6317.description"] = "Des dents sur un champ d’eau de lac. Les nains approuveraient, puis compteraient leurs doigts."
	L["good.core.crest.fish.6317.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6358.description"] = "Un poisson huileux sur fond bleu, luisant. Toutes les couleurs que l’huile pouvait faire, au complet."
	L["good.core.crest.fish.6358.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6359.description"] = "Un lutjan rouge qui monte dans l’eau tiède, pour le pêcheur qui l’a vu dans toutes ses couleurs."
	L["good.core.crest.fish.6359.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6361.description"] = "Un thon aux nageoires arc-en-ciel déployées, des couleurs qui ne s’effacent jamais sur un écu."
	L["good.core.crest.fish.6361.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6362.description"] = "Une morue marbrée sur un bleu profond, têtue comme les rochers où elle se cache."
	L["good.core.crest.fish.6362.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6458.description"] = "Un petit poisson sur une eau trouble, aussi propre qu’il le sera jamais."
	L["good.core.crest.fish.6458.name"] = "Blason : {fish}"
	L["good.core.crest.fish.6522.description"] = "Quelque chose qui a trop d’yeux, sur un champ d’eau malsaine. La preuve d’un estomac solide."
	L["good.core.crest.fish.6522.name"] = "Blason : {fish}"
	L["good.core.crest.fish.8365.description"] = "Une truite à la tête brillante sur un vert de rivière. Le forgeron a cessé de demander."
	L["good.core.crest.fish.8365.name"] = "Blason : {fish}"
	L["good.core.crest.plain.description"] = "Aucun emblème, seulement le nom du propriétaire. Bien des bons pêcheurs n’en ont jamais voulu davantage."
	L["good.core.crest.plain.name"] = "Uni"
	L["good.core.newssign.astro.description"] = "Une étoile tombe, et un astrolabe de laiton tourne autour d’elle jusqu’à ce que son disque s’ouvre sur le ciel nocturne. Les nouvelles se lisent mieux à la lumière des étoiles."
	L["good.core.newssign.astro.name"] = "Astrolabe"
	L["good.core.newssign.coral.description"] = "Une goutte tombe, et une plaque cerclée de perles remonte des éclaboussures, entourée d’algues et de corail. Des bulles montent. Quelque chose, en bas, est en train de lire."
	L["good.core.newssign.coral.name"] = "Corail"
	L["good.core.newssign.kraken.description"] = "Deux tentacules descendent une tablette de pierre couverte d’algues, agrippée par les coins. Elle ruisselle. Les ventouses palpitent. Personne ne demande où est le reste."
	L["good.core.newssign.kraken.name"] = "Kraken"
	L["good.core.newssign.lantern.description"] = "Une lanterne de laiton descend au bout d’une chaîne devant une vitre sombre. Elle s’allume, les lignes apparaissent une à une, et les lucioles restent."
	L["good.core.newssign.lantern.name"] = "Lanterne"
	L["good.core.newssign.scroll.description"] = "Une carte roulée descend derrière un bouchon rouge et blanc. Elle se déroule avec la nouvelle et prend un sceau de cire, pour faire bonne mesure."
	L["good.core.newssign.scroll.name"] = "Parchemin"
	L["good.core.newssign.wood.description"] = "Des planches patinées au bout de deux cordes. Elle descend, se balance, se pose et dit ce qu’elle a à dire. Simple, et fière de l’être."
	L["good.core.newssign.wood.name"] = "Bois"
	L["good.core.soundset.arcade.description"] = "Des bips de pièces et un jingle de niveau, depuis la borne au fond de la taverne. Insérez un poisson pour continuer."
	L["good.core.soundset.arcade.name"] = "Borne d’arcade"
	L["good.core.soundset.boing.description"] = "Un ressort, une claque et un plouf, dans l’ordre que décide le poisson. Personne n’est blessé."
	L["good.core.soundset.boing.name"] = "Boïng !"
	L["good.core.soundset.bubbleworks.description"] = "De grosses bulles rondes qui éclatent en remontant des profondeurs, et quelque part au loin une baleine très aimable qui dit bonjour."
	L["good.core.soundset.bubbleworks.name"] = "Fabrique à bulles"
	L["good.core.soundset.dragonroost.description"] = "Un dragon sur une haute corniche, des battements d’ailes et un cor qui répond à son rugissement. Le poisson valait bien de le réveiller."
	L["good.core.soundset.dragonroost.name"] = "Perchoir du dragon"
	L["good.core.soundset.driftwood.description"] = "De doux coups de bois, comme une coque qui heurte la jetée."
	L["good.core.soundset.driftwood.name"] = "Bois flotté"
	L["good.core.soundset.dulcimer.description"] = "Un tympanon dans le coin d’une taverne du port, frappé vif et clair."
	L["good.core.soundset.dulcimer.name"] = "Tympanon de taverne"
	L["good.core.soundset.frost.description"] = "Des glaçons qui tintent l’un contre l’autre dans un vent froid, et résonnent longtemps après s’être immobilisés."
	L["good.core.soundset.frost.name"] = "Carillon de givre"
	L["good.core.soundset.gilded.description"] = "De petites cloches claires. Un peu grandiose pour un maquereau, et il ne s’en porte pas plus mal."
	L["good.core.soundset.gilded.name"] = "Doré"
	L["good.core.soundset.gizmo.description"] = "Un tic-tac mécanique, un ressort qui se détend et deux bips joyeux. Ça marche, presque certainement."
	L["good.core.soundset.gizmo.name"] = "Bidule gnome"
	L["good.core.soundset.glass.description"] = "Des flotteurs de verre vert qui s’entrechoquent sur un filet, avec des bulles qui remontent à côté."
	L["good.core.soundset.glass.name"] = "Flotteurs de verre"
	L["good.core.soundset.goblintill.description"] = "La caisse enregistreuse d’un gobelin qui se déclenche comme un gros lot, des pièces partout, et le propriétaire qui en rit. Ni repris ni échangé."
	L["good.core.soundset.goblintill.name"] = "Caisse gobeline"
	L["good.core.soundset.harp.description"] = "Une harpe dans une clairière, un bref balayage de cordes et les feuilles qui répondent."
	L["good.core.soundset.harp.name"] = "Harpe de la clairière"
	L["good.core.soundset.kalimba.description"] = "Un piano à pouces près d’une eau qui court, deux notes et un petit grésillement, comme si le ruisseau les avait pincées."
	L["good.core.soundset.kalimba.name"] = "Kalimba du ruisseau"
	L["good.core.soundset.kazoo.description"] = "Un mirliton, une flûte à coulisse et une langue de belle-mère qui défilent dans le port comme un jour de fête. C’en est un, maintenant."
	L["good.core.soundset.kazoo.name"] = "Parade de mirlitons"
	L["good.core.soundset.laser.description"] = "Un gadget gnome qui grésille, oscille et bourdonne, puis termine par un joyeux ding. Pas une arme, sans doute."
	L["good.core.soundset.laser.name"] = "Laser gnome"
	L["good.core.soundset.marimba.description"] = "De chaudes lames de bois, montées vite le long de la gamme comme une vague qui arrive."
	L["good.core.soundset.marimba.name"] = "Marimba du rivage"
	L["good.core.soundset.mrglglgl.description"] = "Un murloc a repéré votre prise et a son avis dessus. Mrgl ! Mrglglgl !"
	L["good.core.soundset.mrglglgl.name"] = "Mrglglgl"
	L["good.core.soundset.musicbox.description"] = "Un petit air mécanique sorti d’une boîte avec un poisson peint sur le couvercle. Deux tours de clé, pas plus."
	L["good.core.soundset.musicbox.name"] = "Boîte à musique"
	L["good.core.soundset.parrot.description"] = "Un perroquet des quais, un canon de navire et une cloche. Le perroquet annonce, les pirates applaudissent."
	L["good.core.soundset.parrot.name"] = "Perroquet pirate"
	L["good.core.soundset.rain.description"] = "Des gouttes qui tombent sur l’eau calme, l’une après l’autre, et le léger murmure de la pluie derrière."
	L["good.core.soundset.rain.name"] = "Pluie sur le lac"
	L["good.core.soundset.shipbell.description"] = "La cloche de laiton du mât, sonnée pour la prise, avec le cordage et les membrures qui grincent dessous."
	L["good.core.soundset.shipbell.name"] = "Cloche de bord"
	L["good.core.soundset.silithid.description"] = "Un essaim de guêpes silithides qui passe en bourdonnant près de votre prise, en cliquetant et en stridulant. Gardez les doigts dans la barque."
	L["good.core.soundset.silithid.name"] = "Essaim silithide"
	L["good.core.soundset.slime.description"] = "Quelque chose de vert et de tremblotant est ravi de votre prise et l’approuve d’un bruit mouillé."
	L["good.core.soundset.slime.name"] = "L’heure de la gelée"
	L["good.core.soundset.squeaky.description"] = "Un canard en caoutchouc qui a de grandes opinions sur votre prise. Deux couinements, un plouf, aucun regret."
	L["good.core.soundset.squeaky.name"] = "Couinant"
	L["good.core.soundset.steelpan.description"] = "De vifs tambours d’acier venus d’un lagon chaud, deux notes qui disent que la marée est de votre côté."
	L["good.core.soundset.steelpan.name"] = "Lagon des tambours d’acier"
	L["good.core.soundset.succubus.description"] = "Une succube dans la charpente, qui ronronne et ricane au sujet de votre prise. N’en dites rien à personne."
	L["good.core.soundset.succubus.name"] = "Murmure de la succube"
	L["good.core.soundset.wardrums.description"] = "Des tambours graves et un cor bas depuis les collines : une prise annoncée comme le début d’une marche."
	L["good.core.soundset.wardrums.name"] = "Tambours de guerre"
	L["good.core.toaststyle.arcane.description"] = "Inscrit dans une cité flottante aux tours violettes, par un mage qui voulait savoir si l’on pouvait invoquer un poisson. On pouvait. Il n’a pas apprécié."
	L["good.core.toaststyle.arcane.name"] = "Sceau arcanique"
	L["good.core.toaststyle.birch.description"] = "Écrit sur une bande d’écorce pelée et noué de ficelle. L’encre pénètre et reste."
	L["good.core.toaststyle.birch.name"] = "Rouleau de bouleau"
	L["good.core.toaststyle.bottle.description"] = "Roulé, bouché et confié à la marée. Revenu avec une meilleure prise qu’au départ."
	L["good.core.toaststyle.bottle.name"] = "Bouteille de verre flotté"
	L["good.core.toaststyle.chart.description"] = "Arrachée à une carte que personne n’aurait dû vendre. Sondes, loxodromies et une rose des vents qui indique toujours le nord."
	L["good.core.toaststyle.chart.name"] = "Carte marine"
	L["good.core.toaststyle.foil.description"] = "La rare, tirée du paquet du premier coup. Tenez-la à la lumière et tout le lac la traverse."
	L["good.core.toaststyle.foil.name"] = "Carte rare brillante"
	L["good.core.toaststyle.folio.description"] = "Feuille d’or, lapis et vermillon, posés sur vélin par un scribe qui avait trop de temps et pas assez de poissons."
	L["good.core.toaststyle.folio.name"] = "Folio enluminé"
	L["good.core.toaststyle.frost.description"] = "Laissé dehors toute la nuit sur la glace. Le givre a poussé depuis les coins pendant que l’encre était encore fraîche."
	L["good.core.toaststyle.frost.name"] = "Mordu par le gel"
	L["good.core.toaststyle.glacier.description"] = "Taillé dans le cœur bleu d’un glacier plus vieux que la première barque, là où le froid traverse tout et où la lumière ressort changée de l’autre côté."
	L["good.core.toaststyle.glacier.name"] = "Cœur de glacier"
	L["good.core.toaststyle.goblin.description"] = "Imprimé sur un téléscripteur qui ne s’arrête jamais. Les rivets sont porteurs. Personne ne sait à quoi sert l’engrenage."
	L["good.core.toaststyle.goblin.name"] = "Téléscripteur gobelin"
	L["good.core.toaststyle.hive.description"] = "Abandonnée par quelque chose de grand qui vit sous les dunes et remonte quand le sable chante. Les plaques bourdonnent encore ; les yeux regardent encore."
	L["good.core.toaststyle.hive.name"] = "Chitine de la ruche"
	L["good.core.toaststyle.kelp.description"] = "Un dos enveloppé de varech et clouté de perles, la page brillante comme l’intérieur d’un coquillage."
	L["good.core.toaststyle.kelp.name"] = "Varech et perle"
	L["good.core.toaststyle.lanternglow.description"] = "Une lampe chaude qui luit derrière chaque prise, pour les pêcheurs qui restent dehors après la nuit tombée."
	L["good.core.toaststyle.lanternglow.name"] = "Lueur de lanterne"
	L["good.core.toaststyle.leaf.description"] = "Une seule grande feuille, pressée à plat entre deux gros livres et séchée jusqu’à l’or. Les nervures tiennent lieu de lignes."
	L["good.core.toaststyle.leaf.name"] = "Feuille pressée"
	L["good.core.toaststyle.magma.description"] = "Prélevée dans une rivière de roche en fusion par quelqu’un qui avait oublié sa poêle. La croûte refroidit ; la prise, non. Ne pas toucher."
	L["good.core.toaststyle.magma.name"] = "Coulée de magma"
	L["good.core.toaststyle.moon.description"] = "Un vélin bleu nuit écrit à l’argent, pour les prises qui arrivent après les lanternes."
	L["good.core.toaststyle.moon.name"] = "Vélin au clair de lune"
	L["good.core.toaststyle.ooze.description"] = "Quelque chose est sorti du marais en rampant et a décidé que votre prise était ce qu’il avait mangé de meilleur. Il digère encore les arêtes."
	L["good.core.toaststyle.ooze.name"] = "Limon"
	L["good.core.toaststyle.page.description"] = "Une page fraîchement arrachée au journal de bord et épinglée à un dos de cuir. Garniture de laiton, encre rouge."
	L["good.core.toaststyle.page.name"] = "Page arrachée"
	L["good.core.toaststyle.pirate.description"] = "Arraché au pont d’un navire qui n’a jamais hissé qu’un seul pavillon. L’équipage a disparu depuis longtemps ; le perroquet se souvient de chaque poisson et vous les racontera, bruyamment."
	L["good.core.toaststyle.pirate.name"] = "Pavillon noir"
	L["good.core.toaststyle.ripple.description"] = "Du cuir bleu et une garniture d’argent, avec de légers cercles qui s’étendent sur la page comme si quelque chose venait de mordre."
	L["good.core.toaststyle.ripple.name"] = "Ondes"
	L["good.core.toaststyle.robot.description"] = "Construit pour pêcher pendant que son inventeur dormait. Il n’a jamais dormi, jamais cligné des yeux, et n’a jamais laissé filer un seul poisson. L’œil rouge signifie qu’il réfléchit."
	L["good.core.toaststyle.robot.name"] = "Pêcheur mécanique"
	L["good.core.toaststyle.rune.description"] = "Pas du papier du tout : une plaque de bronze, la prise martelée dedans et les runes taillées autour pour qu’elle reste honnête."
	L["good.core.toaststyle.rune.name"] = "Plaque runique"
	L["good.core.toaststyle.ship.description"] = "Une page du journal de bord, liée à un dos de toile à voile. Colonnes de marées réglées en bleu marine, une ancre dans la marge."
	L["good.core.toaststyle.ship.name"] = "Journal de bord"
	L["good.core.toaststyle.sonar.description"] = "Construit par un ingénieur qui voulait voir les poissons avant qu’ils le voient. Il bourdonne, il émet des bips, et il ne s’est jamais trompé sur un bip."
	L["good.core.toaststyle.sonar.name"] = "Sonar Scope"
	L["good.core.toaststyle.spider.description"] = "Tissée en travers de la fenêtre du hangar à bateaux pendant la nuit. Ce qui s’y est pris était à elle d’abord ; elle vous prête seulement le nom."
	L["good.core.toaststyle.spider.name"] = "Toile de la veuve"
	L["good.core.toaststyle.storm.description"] = "La prise que vous avez faite quand tous les gens raisonnables étaient rentrés. Le fanion dit tempête ; le pêcheur dit encore un lancer."
	L["good.core.toaststyle.storm.name"] = "Front d’orage"
	L["good.core.toaststyle.tidepool.description"] = "Une page tombée à l’eau et ressortie. Du sable dans le pli, un coquillage oublié."
	L["good.core.toaststyle.tidepool.name"] = "Flaque de marée"
	L["variety.12238.barred.description"] = "De larges bandes sombres qui pâlissent quand il se repose. Il se repose beaucoup."
	L["variety.12238.barred.name"] = "Rayé"
	L["variety.12238.bigmouth.description"] = "Une gueule à avaler une lanterne. C’est peut-être déjà fait."
	L["variety.12238.bigmouth.name"] = "Grande-gueule"
	L["variety.12238.brown.description"] = "Brun des estuaires boueux. Fait le même ragoût."
	L["variety.12238.brown.name"] = "Brun"
	L["variety.12238.coast-grey.description"] = "Gris marbré de gris plus sombre, large comme un bouclier. Ne bouge que s’il le faut."
	L["variety.12238.coast-grey.name"] = "Gris de côte"
	L["variety.12238.moon-pale.description"] = "Gris pâle, comme si la lune l’avait décoloré. Meilleur en ragoût qu’à première vue."
	L["variety.12238.moon-pale.name"] = "Pâle de lune"
	L["variety.12238.moonkissed.description"] = "Des points pâles y brillent comme des étoiles sur l’eau sombre. Pris sous la pleine lune, si les histoires disent vrai."
	L["variety.12238.moonkissed.name"] = "Baiser de lune"
	L["variety.12238.mottled.description"] = "Des taches sombres comme des rochers sous une eau peu profonde. Reste immobile et attend."
	L["variety.12238.mottled.name"] = "Marbré"
	L["variety.12238.night-dark.description"] = "Presque noir, du plus profond de la baie. Personne ne le voit avant qu’il morde."
	L["variety.12238.night-dark.name"] = "Noir de nuit"
	L["variety.12238.rust-spotted.description"] = "Des taches de rouille sur du gris, comme une ancre restée dehors trop longtemps."
	L["variety.12238.rust-spotted.name"] = "Taché de rouille"
	L["variety.12238.silverscale.description"] = "Argenté là où il devrait être gris. Les pêcheurs de la côte disent qu’il porte chance. Les pêcheurs de la côte ont besoin de chance."
	L["variety.12238.silverscale.name"] = "Écaille-d’argent"
	L["variety.13422.banded.description"] = "Des anneaux de pierre sombre sur toute sa longueur, comme un pilier sculpté."
	L["variety.13422.banded.name"] = "Annelée"
	L["variety.13422.bedrock-ancient.description"] = "D’énormes écailles de pierre, fendues et luisantes d’ambre dans les joints. Aussi vieille que la falaise d’où elle vient, à la voir."
	L["variety.13422.bedrock-ancient.name"] = "Ancienne du socle"
	L["variety.13422.gold-veined.description"] = "L’or court dans le gris comme le minerai dans la roche. On a vu des joailliers pleurer."
	L["variety.13422.gold-veined.name"] = "Veinée d’or"
	L["variety.13422.greenstone.description"] = "Des écailles vert mousse. On dirait qu’elle a dormi un siècle au fond d’une rivière."
	L["variety.13422.greenstone.name"] = "Pierre verte"
	L["variety.13422.marble.description"] = "Blanche veinée de gris, comme le sol d’un temple. Les armuriers se la disputent."
	L["variety.13422.marble.name"] = "Marbre"
	L["variety.13422.moray-spotted.description"] = "Des taches sombres partout, comme la peau d’une murène. Tout aussi ravie de vous voir."
	L["variety.13422.moray-spotted.name"] = "Tachetée comme une murène"
	L["variety.13422.obsidian.description"] = "Des écailles noires et vitreuses, chacune tranchante. À manier par la queue, et avec soin."
	L["variety.13422.obsidian.name"] = "Obsidienne"
	L["variety.13422.pebble-scaled.description"] = "Des écailles comme de petits galets gris. Les armuriers paient bien. L’anguille n’est pas d’accord."
	L["variety.13422.pebble-scaled.name"] = "Écailles de galet"
	L["variety.13422.sandstone.description"] = "Des écailles chaudes couleur de sable, des côtes désertiques. Mord quand même."
	L["variety.13422.sandstone.name"] = "Grès"
	L["variety.13422.slate.description"] = "Gris-bleu, comme une ardoise de toiture. Tout aussi dure à couper."
	L["variety.13422.slate.name"] = "Ardoise"
	L["variety.13754.barred.description"] = "De larges bandes en travers du lustre, comme un poisson paré pour la bataille."
	L["variety.13754.barred.name"] = "Rayé"
	L["variety.13754.bronzeback.description"] = "Un dos de bronze et un ventre pâle. Assez lourd pour ancrer un esquif."
	L["variety.13754.bronzeback.name"] = "Dos-de-bronze"
	L["variety.13754.cobalt.description"] = "Un bleu cobalt profond aux reflets violets. On dirait un bijou. Pèse comme une enclume."
	L["variety.13754.cobalt.name"] = "Cobalt"
	L["variety.13754.dappled.description"] = "Des taches claires sur le dos, comme le soleil à travers une eau peu profonde."
	L["variety.13754.dappled.name"] = "Pommelé"
	L["variety.13754.green-glass.description"] = "Vert comme une bouteille tenue à la lumière. Tout aussi lourd."
	L["variety.13754.green-glass.name"] = "Verre vert"
	L["variety.13754.humpbacked.description"] = "Une bosse de muscle derrière la tête. Tire comme une mule."
	L["variety.13754.humpbacked.name"] = "Bossu"
	L["variety.13754.mirror.description"] = "Si brillant que le pêcheur pourrait s’y recoiffer. La plupart ne le font pas, après le combat."
	L["variety.13754.mirror.name"] = "Miroir"
	L["variety.13754.onyx.description"] = "Un lustre noir, comme laqué. Avale la lumière, et l’hameçon."
	L["variety.13754.onyx.name"] = "Onyx"
	L["variety.13754.polished.description"] = "Trapu, bleu et poli comme une botte neuve. Tire comme quelque chose de deux fois sa taille."
	L["variety.13754.polished.name"] = "Poli"
	L["variety.13754.tidemight.description"] = "Des lignes de lumière marine courent sous le lustre. Il tire comme si la marée elle-même était au bout."
	L["variety.13754.tidemight.name"] = "Force-des-marées"
	L["variety.13755.blueflash.description"] = "Lance un éclair bleu quand on le touche. Il n’aime pas qu’on le touche."
	L["variety.13755.blueflash.name"] = "Éclair bleu"
	L["variety.13755.blushing.description"] = "Rouge de partout, comme les calmars quand on les surprend. D’habitude, c’est le pêcheur."
	L["variety.13755.blushing.name"] = "Rougissant"
	L["variety.13755.brindled.description"] = "Des rayures sombres le long du manteau, comme le givre qui fend une vitre."
	L["variety.13755.brindled.name"] = "Bringé"
	L["variety.13755.crimson.description"] = "Cramoisi de partout, la couleur d’un avertissement. Crache deux fois plus d’encre."
	L["variety.13755.crimson.name"] = "Cramoisi"
	L["variety.13755.frost-pink.description"] = "Rose pâle, constellé de taches sombres qui vont et viennent au rythme de son souffle. Arrive avec le givre."
	L["variety.13755.frost-pink.name"] = "Rose givré"
	L["variety.13755.frostlight.description"] = "Luit d’un bleu pâle dans le noir, comme la lune sur la neige fraîche. Ne se voit que par les plus grands froids."
	L["variety.13755.frostlight.name"] = "Lueur de givre"
	L["variety.13755.glassfrost.description"] = "Clair comme la glace, givré sur les bords. Fond un peu dans la main, ou en a l’air."
	L["variety.13755.glassfrost.name"] = "Givre de verre"
	L["variety.13755.long-armed.description"] = "Des bras deux fois plus longs que d’ordinaire. Encore plus à démêler, ce qui semblait impossible."
	L["variety.13755.long-armed.name"] = "Long-bras"
	L["variety.13755.milky.description"] = "Blanc et presque transparent. Facile à perdre dans la glace."
	L["variety.13755.milky.name"] = "Laiteux"
	L["variety.13755.ring-spotted.description"] = "Des anneaux sombres sur le manteau, comme une rangée d’yeux qui vous observent."
	L["variety.13755.ring-spotted.name"] = "Ocellé"
	L["variety.13756.bronze.description"] = "Bronze aux bandes légères, des eaux rocheuses. Saute plus que les vertes."
	L["variety.13756.bronze.name"] = "Bronze"
	L["variety.13756.bucketmouth.description"] = "Une gueule comme un seau. Avale les leurres tout ronds, et parfois de petits canards."
	L["variety.13756.bucketmouth.name"] = "Gueule-de-seau"
	L["variety.13756.golden.description"] = "Dorée avec une bande bronze. Un après-midi d’été en forme de poisson."
	L["variety.13756.golden.name"] = "Dorée"
	L["variety.13756.lateral-lined.description"] = "Verte avec une ligne sombre sur chaque flanc. Se tapit sous tout ce qui fait de l’ombre."
	L["variety.13756.lateral-lined.name"] = "Ligne latérale"
	L["variety.13756.lily-pad.description"] = "Marbrée comme un étang plein de nénuphars, ce qui est exactement là où elle se cache."
	L["variety.13756.lily-pad.name"] = "Nénuphar"
	L["variety.13756.midsummer.description"] = "Luit d’un or chaud, comme la plus longue soirée de l’année. Ne se prend qu’au plus fort de l’été."
	L["variety.13756.midsummer.name"] = "Solstice d’été"
	L["variety.13756.red-eyed.description"] = "Des yeux rouges comme un coucher de soleil d’été. Mange le plus dans la chaleur du soir."
	L["variety.13756.red-eyed.name"] = "Yeux-rouges"
	L["variety.13756.shadow.description"] = "Vert-noir et difficile à voir. Vit à l’ombre et la préfère."
	L["variety.13756.shadow.name"] = "Ombre"
	L["variety.13756.sun-bleached.description"] = "Pâlie par les eaux d’été peu profondes, la bande réduite à une trace. Tiède à tenir."
	L["variety.13756.sun-bleached.name"] = "Délavée par le soleil"
	L["variety.13756.tiger.description"] = "Des bandes sombres brisées comme des rayures de tigre. Se bat comme un tigre, brièvement."
	L["variety.13756.tiger.name"] = "Tigrée"
	L["variety.13757.blackout.description"] = "Noire et silencieuse jusqu’à ce qu’on la touche. Après, plus silencieuse du tout."
	L["variety.13757.blackout.name"] = "Nuit noire"
	L["variety.13757.bolt-striped.description"] = "Des zigzags jaunes sur les flancs, comme un éclair dessiné par un enfant."
	L["variety.13757.bolt-striped.name"] = "Zébrée d’éclairs"
	L["variety.13757.ember-bellied.description"] = "Un ventre orange, comme une anguille électrique des rivières chaudes. Mord avec une étincelle."
	L["variety.13757.ember-bellied.name"] = "Ventre-de-braise"
	L["variety.13757.long.description"] = "Une nageoire sur toute la longueur du corps. Elle ondule comme un drapeau dans la tempête."
	L["variety.13757.long.name"] = "Longue"
	L["variety.13757.ozone.description"] = "Sent la pluie après l’orage. L’air autour d’elle devient piquant."
	L["variety.13757.ozone.name"] = "Ozone"
	L["variety.13757.slate.description"] = "Grise comme les nuages d’orage. Bourdonne sur une note plus grave."
	L["variety.13757.slate.name"] = "Ardoise"
	L["variety.13757.spark-spotted.description"] = "Des taches pâles qui crépitent quand elle se débat. Les gants ne servent à rien."
	L["variety.13757.spark-spotted.name"] = "Tachée d’étincelles"
	L["variety.13757.stormcaller.description"] = "Des éclairs bleus se ramifient sur son corps jusque dans l’eau. Les nuages s’amassent tant qu’elle est au bout de la ligne, ou en ont l’air."
	L["variety.13757.stormcaller.name"] = "Mande-tempête"
	L["variety.13757.thunder-dark.description"] = "Olive sombre et bourdonnante. Ça picote. Ne la léchez pas."
	L["variety.13757.thunder-dark.name"] = "Sombre d’orage"
	L["variety.13757.white-bolt.description"] = "Blanche comme un éclair, et brièvement aveuglante quand elle se tord."
	L["variety.13757.white-bolt.name"] = "Éclair blanc"
	L["variety.13758.cinder.description"] = "Gris cendre aux ouïes rouges et luisantes, comme une braise tirée d’un feu éteint."
	L["variety.13758.cinder.name"] = "Escarbille"
	L["variety.13758.ember-gilled.description"] = "Rayé comme une perche, les ouïes rouges comme des braises. L’allure habituelle, et le caractère habituel."
	L["variety.13758.ember-gilled.name"] = "Ouïes de braise"
	L["variety.13758.fel-scarred.description"] = "Un feu vert court sous les écailles, là où devrait être le rouge. Il vient d’une eau qui se souvient d’une corruption."
	L["variety.13758.fel-scarred.name"] = "Balafré de gangrefeu"
	L["variety.13758.fire-gilled.description"] = "Les ouïes luisent vraiment. Personne n’est sûr que l’eau était assez froide."
	L["variety.13758.fire-gilled.name"] = "Ouïes de feu"
	L["variety.13758.ghost.description"] = "Pâle, aux ouïes roses et aux bandes légères. Paraît froid même en été."
	L["variety.13758.ghost.name"] = "Fantôme"
	L["variety.13758.golden.description"] = "Doré aux ouïes écarlates. On dirait qu’il sort de la fontaine d’un seigneur."
	L["variety.13758.golden.name"] = "Doré"
	L["variety.13758.olive.description"] = "Olive plus sombre, des rivières envahies de végétation. Les ouïes n’en brillent que plus."
	L["variety.13758.olive.name"] = "Olive"
	L["variety.13758.redfin.description"] = "Des nageoires aussi rouges que les ouïes. Tout le poisson a l’air en colère, parce qu’il l’est."
	L["variety.13758.redfin.name"] = "Nageoire-rouge"
	L["variety.13758.spotted.description"] = "Des taches au lieu des bandes. Même caractère."
	L["variety.13758.spotted.name"] = "Tacheté"
	L["variety.13758.yellow.description"] = "Jaune doré aux bandes sombres. Brillant comme une lampe dans l’eau verte."
	L["variety.13758.yellow.name"] = "Jaune"
	L["variety.13759.crescent-marked.description"] = "Un croissant pâle sur chaque flanc, comme si la lune y avait laissé une empreinte."
	L["variety.13759.crescent-marked.name"] = "Marqué du croissant"
	L["variety.13759.dawn-caught.description"] = "Rose et or, pris quand la nuit finissait. Un poisson de nuit qui a veillé trop tard."
	L["variety.13759.dawn-caught.name"] = "Pris à l’aube"
	L["variety.13759.dusk.description"] = "Dos violet, ventre rose, comme le ciel juste après le coucher du soleil."
	L["variety.13759.dusk.name"] = "Crépuscule"
	L["variety.13759.eclipse.description"] = "Noir, liseré d’or aux nageoires, comme un soleil éteint."
	L["variety.13759.eclipse.name"] = "Éclipse"
	L["variety.13759.indigo.description"] = "Indigo profond. Disparaît dans l’eau dès que la lune se cache."
	L["variety.13759.indigo.name"] = "Indigo"
	L["variety.13759.moonfin.description"] = "Des nageoires blanc argenté qui accrochent le clair de lune. Les pêcheurs apprennent à aimer le noir."
	L["variety.13759.moonfin.name"] = "Nageoire-de-lune"
	L["variety.13759.owl-eyed.description"] = "D’immenses yeux dorés faits pour le noir. Vous rend votre regard."
	L["variety.13759.owl-eyed.name"] = "Yeux de chouette"
	L["variety.13759.star-speckled.description"] = "Des points pâles le long du dos, comme un ciel où quelques étoiles sont sorties."
	L["variety.13759.star-speckled.name"] = "Moucheté d’étoiles"
	L["variety.13759.starfeeder.description"] = "Violet sombre, aux nageoires couleur de nuit. Se nourrit à la lumière des étoiles."
	L["variety.13759.starfeeder.name"] = "Mange-étoiles"
	L["variety.13759.starsong.description"] = "Ses points brillent comme le ciel nocturne et bougent quand il tourne, comme des étoiles qui tournoient. Le silence tombe sur le quai."
	L["variety.13759.starsong.name"] = "Chant d’étoiles"
	L["variety.13760.coin-scaled.description"] = "Argenté, aux écailles pailletées d’or qui accrochent la lumière comme des pièces dans un ruisseau."
	L["variety.13760.coin-scaled.name"] = "Écailles de pièce"
	L["variety.13760.copper.description"] = "Cuivre poli de la tête à la queue. A le goût du saumon, l’allure d’une bouilloire."
	L["variety.13760.copper.name"] = "Cuivre"
	L["variety.13760.hooknose.description"] = "Une mâchoire crochue et féroce, gagnée en remontant la rivière. Prêt à se battre contre un ours."
	L["variety.13760.hooknose.name"] = "Bec-crochu"
	L["variety.13760.morning.description"] = "Teinté de pêche le long du ventre, comme la première lumière sur une rivière."
	L["variety.13760.morning.name"] = "Matin"
	L["variety.13760.noonday.description"] = "Doré tout le long du dos, comme une rivière à midi."
	L["variety.13760.noonday.name"] = "Plein midi"
	L["variety.13760.red-run.description"] = "Devenu rouge pour la remontée du frai, la tête verte. Les bonnes années, la rivière en devient rouge."
	L["variety.13760.red-run.name"] = "Remontée rouge"
	L["variety.13760.river-dark.description"] = "Plus sombre, des rivières ombragées. Les paillettes d’or n’en ressortent que mieux."
	L["variety.13760.river-dark.name"] = "Sombre de rivière"
	L["variety.13760.silverbright.description"] = "D’un argent éclatant, tout juste sorti de la mer. À peine une paillette d’or."
	L["variety.13760.silverbright.name"] = "Argent vif"
	L["variety.13760.sunfire.description"] = "Chaque écaille dorée comme un petit soleil. Chaud comme une pierre d’âtre. Difficile à regarder en face."
	L["variety.13760.sunfire.name"] = "Feu solaire"
	L["variety.13760.twilight.description"] = "Violet et orange, comme la dernière lumière sur la rivière. Disparu à la nuit noire."
	L["variety.13760.twilight.name"] = "Entre-chien-et-loup"
	L["variety.13888.abyssal.description"] = "Une lumière violette luit aux jointures de sa carapace. Remonté d’eaux très profondes, et visiblement agacé de l’avoir fait."
	L["variety.13888.abyssal.name"] = "Abyssal"
	L["variety.13888.barnacled.description"] = "Des balanes sur toute la carapace. N’a pas mué depuis longtemps, et ne s’en excuse pas."
	L["variety.13888.barnacled.name"] = "Couvert de balanes"
	L["variety.13888.bigclaw.description"] = "Une pince deux fois plus grosse que l’autre. Sait exactement laquelle utiliser."
	L["variety.13888.bigclaw.name"] = "Grosse-pince"
	L["variety.13888.blue-black.description"] = "Une carapace bleu-noir, légèrement mouchetée, pinces en avant. Le genre qui se cache sous chaque rocher de la baie."
	L["variety.13888.blue-black.name"] = "Bleu-noir"
	L["variety.13888.calico.description"] = "Orange et noir par plaques, comme un chat écaille de tortue. Presque personne n’y croit."
	L["variety.13888.calico.name"] = "Écaille-de-tortue"
	L["variety.13888.ghost.description"] = "Blanc comme l’os. Même les pinces sont pâles. Le caractère, lui, ne l’est pas."
	L["variety.13888.ghost.name"] = "Fantôme"
	L["variety.13888.mud-brown.description"] = "Brun des plateaux vaseux. Pince tout aussi fort."
	L["variety.13888.mud-brown.name"] = "Brun de vase"
	L["variety.13888.red-banded.description"] = "Des bandes rouges en travers de la queue. A l’air déjà à moitié cuit. Ne l’est pas."
	L["variety.13888.red-banded.name"] = "Bagué de rouge"
	L["variety.13888.sapphire.description"] = "Bleu vif de partout. Un sur un très grand nombre. Pince comme les autres."
	L["variety.13888.sapphire.name"] = "Saphir"
	L["variety.13888.sea-green.description"] = "Vert-noir, comme un homard des mers plus froides."
	L["variety.13888.sea-green.name"] = "Vert de mer"
	L["variety.13889.ashen.description"] = "Gris comme la cendre, des eaux proches des terres flétries. Toujours bon à manger, dit-on."
	L["variety.13889.ashen.name"] = "Cendré"
	L["variety.13889.crystal.description"] = "Clair comme la glace par endroits. La poêle semble déplacée, on ne sait pourquoi."
	L["variety.13889.crystal.name"] = "Cristal"
	L["variety.13889.frost-white.description"] = "Argent pâle, légèrement moucheté, froid au toucher même après des heures au soleil."
	L["variety.13889.frost-white.name"] = "Blanc de givre"
	L["variety.13889.hooknose.description"] = "Une mâchoire crochue et un regard froid. Du givre sur des moustaches qu’il n’a pas."
	L["variety.13889.hooknose.name"] = "Bec-crochu"
	L["variety.13889.hot-spring.description"] = "Aux teintes plus chaudes, des eaux où jaillissent les sources. Il fume quand on le sort de l’eau."
	L["variety.13889.hot-spring.name"] = "Source chaude"
	L["variety.13889.pearl.description"] = "Un éclat nacré, sans la moindre tache. On le dirait sculpté."
	L["variety.13889.pearl.name"] = "Perle"
	L["variety.13889.silverblue.description"] = "Un reflet bleu le long du dos, venu de l’eau des glaciers."
	L["variety.13889.silverblue.name"] = "Bleu argent"
	L["variety.13889.snowflake.description"] = "Des points d’un blanc éclatant sur l’argent, comme de la neige sur un lac gelé."
	L["variety.13889.snowflake.name"] = "Flocon"
	L["variety.13889.spawn-blush.description"] = "Une rougeur rose sur les flancs pour le frai. Rare dans une eau si froide."
	L["variety.13889.spawn-blush.name"] = "Rose du frai"
	L["variety.13889.wintersheen.description"] = "Des motifs de givre couvrent chaque écaille et luisent d’un bleu léger. Il ne dégèle jamais, pas même dans la poêle."
	L["variety.13889.wintersheen.name"] = "Lustre d’hiver"
	L["variety.13890.ancient-bulwark.description"] = "Des plaques épaisses comme des boucliers, gravées de vieilles lignes qui luisent d’or. Comme si quelqu’un l’avait forgé il y a longtemps, puis mis à l’eau."
	L["variety.13890.ancient-bulwark.name"] = "Rempart ancien"
	L["variety.13890.battle-scarred.description"] = "Des plaques cabossées et de vieilles entailles. Ce qui a voulu le manger a renoncé."
	L["variety.13890.battle-scarred.name"] = "Couturé de cicatrices"
	L["variety.13890.bony-backed.description"] = "Des plaques osseuses le long du dos, comme un esturgeon. L’armure dehors, le caractère dedans."
	L["variety.13890.bony-backed.name"] = "Dos-d’os"
	L["variety.13890.bronze-plated.description"] = "Des plaques couleur de vieux bronze. Digne d’une parade."
	L["variety.13890.bronze-plated.name"] = "Plaqué de bronze"
	L["variety.13890.gilded.description"] = "Des plaques bordées d’or, comme l’armure de parade d’un chevalier. Se bat comme un chevalier, aussi."
	L["variety.13890.gilded.name"] = "Doré à l’or fin"
	L["variety.13890.iron-plated.description"] = "Des plaques grises comme une armure de fer. Prévoyez un couteau plus lourd."
	L["variety.13890.iron-plated.name"] = "Plaqué de fer"
	L["variety.13890.moss-backed.description"] = "De la mousse verte sur ses plaques. N’a pas bougé depuis un moment, puis soudain si."
	L["variety.13890.moss-backed.name"] = "Dos moussu"
	L["variety.13890.ore-plated.description"] = "Des plaques à l’éclat gris-vert, comme le minerai le plus dur des montagnes. Le couteau renonce le premier."
	L["variety.13890.ore-plated.name"] = "Plaqué de minerai"
	L["variety.13890.ring-plated.description"] = "Des plaques en anneaux réguliers, comme une cotte de mailles à bandes."
	L["variety.13890.ring-plated.name"] = "Annelé"
	L["variety.13890.spiked.description"] = "Chaque plaque se termine par une pointe. Les pêcheurs avisés prennent l’épuisette."
	L["variety.13890.spiked.name"] = "Hérissé"
	L["variety.13893.abyss-dark.description"] = "Bleu-noir, de la fosse la plus profonde de la baie. Tire comme si la fosse voulait le reprendre."
	L["variety.13893.abyss-dark.name"] = "Noir d’abysse"
	L["variety.13893.barred.description"] = "De larges bandes sombres sur les flancs, comme les membrures d’une coque."
	L["variety.13893.barred.name"] = "Rayé"
	L["variety.13893.big-blue.description"] = "Énorme, bleu et large. Les deux mains, et sans doute un ami."
	L["variety.13893.big-blue.name"] = "Grand bleu"
	L["variety.13893.golden.description"] = "Un géant doré. Personne ne croit l’histoire sans le poisson."
	L["variety.13893.golden.name"] = "Doré"
	L["variety.13893.hump-shouldered.description"] = "Une grosse bosse derrière la tête. Bâti comme un pieu de quai."
	L["variety.13893.hump-shouldered.name"] = "Épaules bossues"
	L["variety.13893.leviathans-get.description"] = "Des lignes luisantes comme de vieilles runes le long des flancs. Les plus vieilles histoires de la baie parlent de quelque chose de plus gros. C’est un début."
	L["variety.13893.leviathans-get.name"] = "Rejeton du léviathan"
	L["variety.13893.old-scarback.description"] = "Des cicatrices de dents plus grandes que tout ce qu’un pêcheur voudrait croiser."
	L["variety.13893.old-scarback.name"] = "Vieux Dos-balafré"
	L["variety.13893.sea-green.description"] = "Vert comme l’eau profonde. Il faut être trois pour le hisser dans la barque."
	L["variety.13893.sea-green.name"] = "Vert de mer"
	L["variety.13893.spotted.description"] = "Des taches pâles sur un dos sombre, comme l’écume sur une vague."
	L["variety.13893.spotted.name"] = "Tacheté"
	L["variety.13893.storm-grey.description"] = "Gris comme la baie dans la tempête. On dirait qu’il pèse autant."
	L["variety.13893.storm-grey.name"] = "Gris de tempête"
	L["variety.1467.barred.description"] = "De légères bandes sur les flancs, comme en portent les jeunes. Certains ne les perdent jamais."
	L["variety.1467.barred.name"] = "Rayé"
	L["variety.1467.blue-cheeked.description"] = "Deux lignes bleues sur chaque joue, comme des peintures de guerre pour une toute petite guerre."
	L["variety.1467.blue-cheeked.name"] = "Joues-bleues"
	L["variety.1467.copper-breasted.description"] = "Un poitrail comme une bouilloire polie. Les cuisiniers hésitent, brièvement."
	L["variety.1467.copper-breasted.name"] = "Poitrail de cuivre"
	L["variety.1467.ember-spotted.description"] = "Les taches virent au rouge aux mois chauds, comme s’il s’était assis trop près du feu."
	L["variety.1467.ember-spotted.name"] = "Taché de braise"
	L["variety.1467.golden.description"] = "Tout le vert est parti, il ne reste que l’or. Les hérons le voient depuis l’autre rive du lac."
	L["variety.1467.golden.name"] = "Doré"
	L["variety.1467.midnight.description"] = "Noir comme la vase du lac, taches comprises. Facile à manquer, et c’est un peu le but."
	L["variety.1467.midnight.name"] = "Minuit"
	L["variety.1467.pale-shallows.description"] = "Décoloré par les hauts-fonds tièdes et les longs après-midi. Les taches se donnent à peine la peine."
	L["variety.1467.pale-shallows.name"] = "Pâle des hauts-fonds"
	L["variety.1467.peppered.description"] = "Des taches moulues jusqu’au poivre. Même poisson, assaisonnement plus fin."
	L["variety.1467.peppered.name"] = "Poivré"
	L["variety.1467.sunburst.description"] = "Des rayons orange partent de l’œil comme le matin sur une eau calme. Il reste chaud dans la main."
	L["variety.1467.sunburst.name"] = "Rayons de soleil"
	L["variety.1467.sunset-breasted.description"] = "Des flancs olive, des taches sombres, un poitrail comme un coucher de soleil sur le lac. Celui que tout le monde connaît."
	L["variety.1467.sunset-breasted.name"] = "Poitrail couchant"
	L["variety.16967.feeding-barred.description"] = "Des bandes pâles s’allument sur ses flancs, comme chez les thons qui chassent. Pris en plein repas."
	L["variety.16967.feeding-barred.name"] = "Rayé de chasse"
	L["variety.16967.ghostfin.description"] = "Pâle de partout, les nageoires presque transparentes. Nage comme un reflet."
	L["variety.16967.ghostfin.name"] = "Nageoire-fantôme"
	L["variety.16967.gold-belted.description"] = "Une bande dorée de l’œil à la queue. Un poisson de service dans ses plus beaux habits."
	L["variety.16967.gold-belted.name"] = "Ceinture d’or"
	L["variety.16967.imperial.description"] = "Bleu roi profond aux nageoires d’or vif. Trop beau pour rendre service à qui que ce soit."
	L["variety.16967.imperial.name"] = "Impérial"
	L["variety.16967.leaf-lit.description"] = "Une lumière vert pâle bouge sous ses écailles comme le soleil à travers les feuilles. La vieille magie de la forêt est dans ces eaux."
	L["variety.16967.leaf-lit.name"] = "Lueur de feuillage"
	L["variety.16967.mossback.description"] = "Vert-noir sur le dessus, comme si la forêt y avait poussé. Nage lentement, puis très vite."
	L["variety.16967.mossback.name"] = "Dos-de-mousse"
	L["variety.16967.sickle-fin.description"] = "Des nageoires longues et courbes comme des faucilles. Fait pour les longs voyages vers l’aval."
	L["variety.16967.sickle-fin.name"] = "Nageoire-faucille"
	L["variety.16967.silverflank.description"] = "D’un argent plus vif tout le long du flanc. Les nageoires jaunes ont l’air peintes."
	L["variety.16967.silverflank.name"] = "Flanc-d’argent"
	L["variety.16967.verdant.description"] = "Un reflet vert le long du dos, venu de l’eau des rivières sous les grands arbres."
	L["variety.16967.verdant.name"] = "Verdoyant"
	L["variety.16967.yellowfin.description"] = "Dos bleu sombre, ventre argenté, longues nageoires jaunes. Le poisson qui a fait la réputation de la rivière."
	L["variety.16967.yellowfin.name"] = "Nageoire-jaune"
	L["variety.16968.blackback.description"] = "Noir au-dessus, acier en dessous. Frappe depuis l’obscurité."
	L["variety.16968.blackback.name"] = "Dos-noir"
	L["variety.16968.bonecutter.description"] = "Des dents comme des scies à os et un dos couvert de vieilles marques. Les histoires de la côte aride disent qu’il a survécu à trois chasseurs."
	L["variety.16968.bonecutter.name"] = "Coupe-os"
	L["variety.16968.bronze.description"] = "Rayé de bronze, des eaux chaudes. Deux fois plus de caractère."
	L["variety.16968.bronze.name"] = "Bronze"
	L["variety.16968.chevron.description"] = "Des chevrons sombres sur le dos, comme des flèches pointées vers les ennuis."
	L["variety.16968.chevron.name"] = "Chevron"
	L["variety.16968.ghost.description"] = "Blanc et presque transparent, les bandes réduites à leur ombre. Les dents, elles, sont bien solides."
	L["variety.16968.ghost.name"] = "Fantôme"
	L["variety.16968.greyback.description"] = "Gris uni au-dessus, blanc en dessous. Rien que des dents et de l’intention."
	L["variety.16968.greyback.name"] = "Dos-gris"
	L["variety.16968.needlejaw.description"] = "Des dents comme une rangée d’aiguilles. Comptez vos doigts après."
	L["variety.16968.needlejaw.name"] = "Mâchoire-aiguille"
	L["variety.16968.sandstrand.description"] = "Couleur de sable, des hauts-fonds d’une côte aride. Invisible jusqu’à ce qu’il frappe."
	L["variety.16968.sandstrand.name"] = "Grève de sable"
	L["variety.16968.silver-barred.description"] = "Long, argenté et rayé, la mâchoire pleine de dents. Fait pour une seule chose."
	L["variety.16968.silver-barred.name"] = "Rayé d’argent"
	L["variety.16968.spotted.description"] = "Des taches noires près de la queue, comme en prennent les gros. Attend toujours une dispute."
	L["variety.16968.spotted.name"] = "Tacheté"
	L["variety.16969.barred.description"] = "Des bandes bleu pâle sur les flancs, qui s’allument en plein combat. Mieux vu dans les airs, là où il passe le combat."
	L["variety.16969.barred.name"] = "Rayé"
	L["variety.16969.jungle-green.description"] = "Vert comme la jungle derrière la côte. Fait le fier tout pareil."
	L["variety.16969.jungle-green.name"] = "Vert jungle"
	L["variety.16969.royal.description"] = "Bleu roi profond, la voile tachetée d’or. Les pêcheurs le tiennent à tour de rôle."
	L["variety.16969.royal.name"] = "Royal"
	L["variety.16969.silver.description"] = "Plus argenté que bleu. La voile reste éclatante comme toujours."
	L["variety.16969.silver.name"] = "Argenté"
	L["variety.16969.skyleaper.description"] = "Des lignes de lumière bleue ondulent sur la voile quand il saute. Il semble rester en l’air plus longtemps qu’aucun poisson ne le devrait."
	L["variety.16969.skyleaper.name"] = "Saute-ciel"
	L["variety.16969.spotted-sail.description"] = "Dos bleu, ventre argenté, une haute voile constellée de taches. La déploie dès que quelqu’un regarde."
	L["variety.16969.spotted-sail.name"] = "Voile tachetée"
	L["variety.16969.sunset-sail.description"] = "Une voile orange, comme la côte au soir. Saute plus que les bleus."
	L["variety.16969.sunset-sail.name"] = "Voile couchante"
	L["variety.16969.tall-sailed.description"] = "Une voile plus haute que le poisson n’est épais. Le vent la prend au bout de la ligne."
	L["variety.16969.tall-sailed.name"] = "Haute-voile"
	L["variety.16969.violet-sail.description"] = "La voile luit de violet quand il est excité. Il est toujours excité."
	L["variety.16969.violet-sail.name"] = "Voile violette"
	L["variety.16969.white-sail.description"] = "Pâle comme la toile d’un navire. Les marins jurent que c’est signe de beau temps."
	L["variety.16969.white-sail.name"] = "Voile blanche"
	L["variety.16970.barred.description"] = "Des bandes sombres s’allument sur ses flancs quand il est ferré. Il est furieux."
	L["variety.16970.barred.name"] = "Rayé"
	L["variety.16970.bluefin.description"] = "Bleu sur le dos et les nageoires. Plus calme. Pas de beaucoup."
	L["variety.16970.bluefin.name"] = "Nageoire-bleue"
	L["variety.16970.bull-headed.description"] = "Un front haut et massif, comme une coryphène mâle. Charge la barque."
	L["variety.16970.bull-headed.name"] = "Tête-de-taureau"
	L["variety.16970.dorado.description"] = "Vert et or tacheté de bleu, comme un perroquet qui se serait mis à la nage."
	L["variety.16970.dorado.name"] = "Dorado"
	L["variety.16970.emerald.description"] = "Vert pur, sans la moindre trace d’or. Comme une gemme tombée dans le marais."
	L["variety.16970.emerald.name"] = "Émeraude"
	L["variety.16970.fog-pale.description"] = "Pâle, comme si la brume du marais avait déteint sur lui. Se bat comme un banc de brume, puis comme une mule."
	L["variety.16970.fog-pale.name"] = "Pâle de brume"
	L["variety.16970.gold-flanked.description"] = "Plus d’or que de vert. Vire au gris peu après la prise, alors regardez vite."
	L["variety.16970.gold-flanked.name"] = "Flancs d’or"
	L["variety.16970.marsh-lantern.description"] = "Ses taches luisent vert et or dans la brume, comme des lanternes dans un marais. Les gens du coin disent qu’il égare les pêcheurs."
	L["variety.16970.marsh-lantern.name"] = "Lanterne des marais"
	L["variety.16970.reed-green.description"] = "Vert terne, des roseaux brumeux. Difficile à voir jusqu’à ce qu’il saute."
	L["variety.16970.reed-green.name"] = "Vert roseau"
	L["variety.16970.sunfire.description"] = "Orange et or, comme un feu au bord de l’eau. Le marais se tait pour le regarder."
	L["variety.16970.sunfire.name"] = "Feu solaire"
	L["variety.19807.big-spotted.description"] = "Des taches comme des pièces lancées. Quelqu’un prétend toujours que c’est un autre poisson."
	L["variety.19807.big-spotted.name"] = "Grosses taches"
	L["variety.19807.black.description"] = "Noire aux taches de rousseur blanches, comme un ciel nocturne pressé."
	L["variety.19807.black.name"] = "Noire"
	L["variety.19807.champions.description"] = "Chaque tache brille comme une pièce d’or. Le genre de poisson dont on raconte l’histoire pendant des années."
	L["variety.19807.champions.name"] = "De champion"
	L["variety.19807.contest-speckle.description"] = "Gris argenté et tachetée. Chaque concurrent sur le quai la reconnaît au premier coup d’œil."
	L["variety.19807.contest-speckle.name"] = "Mouchetée de concours"
	L["variety.19807.gilded.description"] = "Dorée aux taches brunes. Une foule se forme sur le quai."
	L["variety.19807.gilded.name"] = "Dorée"
	L["variety.19807.lucky-speckle.description"] = "Une tache en forme de fer à cheval. Gardée comme porte-bonheur, puis mangée au déjeuner."
	L["variety.19807.lucky-speckle.name"] = "Tache porte-bonheur"
	L["variety.19807.olive.description"] = "Le dos vert, des hauts-fonds herbeux. Les concurrents se jettent dessus quand même."
	L["variety.19807.olive.name"] = "Olive"
	L["variety.19807.pale.description"] = "Blanche aux taches crème à peine visibles. Fait tourner les têtes à chaque concours."
	L["variety.19807.pale.name"] = "Pâle"
	L["variety.19807.red-speckled.description"] = "Des taches rouges. On la dirait déjà assaisonnée."
	L["variety.19807.red-speckled.name"] = "Mouchetée de rouge"
	L["variety.19807.silver-speckle.description"] = "D’un argent plus vif, de la pleine eau. Mêmes taches."
	L["variety.19807.silver-speckle.name"] = "Mouchetée d’argent"
	L["variety.19975.bloodmud.description"] = "Rouge sombre, d’une vase où l’on faisait jadis des offrandes. Mieux vaut ne pas demander."
	L["variety.19975.bloodmud.name"] = "Vase sanglante"
	L["variety.19975.idol-touched.description"] = "De légères veines rouge-violet luisent sur son dos comme une vieille peinture d’idole. Même les bêtes de ces eaux l’évitent."
	L["variety.19975.idol-touched.name"] = "Touché par l’idole"
	L["variety.19975.jungle-mud.description"] = "Vert-brun, de la vase profonde de la jungle. En a l’odeur, aussi."
	L["variety.19975.jungle-mud.name"] = "Vase de jungle"
	L["variety.19975.long-whiskered.description"] = "De longs barbillons qui traînent dans la vase. Trouve chaque appât, les sent tous."
	L["variety.19975.long-whiskered.name"] = "Longs barbillons"
	L["variety.19975.masked.description"] = "Une bande sombre sur les yeux, comme un masque sculpté. A l’air d’en savoir long."
	L["variety.19975.masked.name"] = "Masqué"
	L["variety.19975.ochre.description"] = "Jaune ocre, comme l’argile dont se peignent les trolls. Ne sent pas meilleur."
	L["variety.19975.ochre.name"] = "Ocre"
	L["variety.19975.pale.description"] = "Pâle comme l’os, d’une eau sous une pierre ancienne. L’odeur survit à la couleur."
	L["variety.19975.pale.name"] = "Pâle"
	L["variety.19975.skunk-striped.description"] = "Une bande pâle de la tête à la queue. Un avertissement, et un honnête."
	L["variety.19975.skunk-striped.name"] = "Rayé de mouffette"
	L["variety.19975.slimeback.description"] = "Brun, visqueux et trapu. Le nez le trouve avant les yeux."
	L["variety.19975.slimeback.name"] = "Dos-gluant"
	L["variety.19975.spotted.description"] = "Des taches sombres sur du brun, comme de la boue éclaboussée sur de la boue."
	L["variety.19975.spotted.name"] = "Tacheté"
	L["variety.21071.banded.description"] = "De légères bandes, comme les rangs d’un jardin d’herbes."
	L["variety.21071.banded.name"] = "Rubanée"
	L["variety.21071.dark-sage.description"] = "Vert profond, des ruisseaux ombragés. Sent plus fort."
	L["variety.21071.dark-sage.name"] = "Sauge sombre"
	L["variety.21071.frost-sage.description"] = "Pâle, chaque écaille bordée de givre. Un goût plus net, allez savoir pourquoi."
	L["variety.21071.frost-sage.name"] = "Sauge givrée"
	L["variety.21071.gold-sage.description"] = "Jaune-vert comme l’herbe sèche de l’été. Sent la longue journée chaude."
	L["variety.21071.gold-sage.name"] = "Sauge dorée"
	L["variety.21071.hillside.description"] = "Vert sauge et tachetée, comme les collines au-dessus du ruisseau d’où elle vient."
	L["variety.21071.hillside.name"] = "Flanc de colline"
	L["variety.21071.lavender-finned.description"] = "Des nageoires couleur lavande. En a un peu le parfum, aussi."
	L["variety.21071.lavender-finned.name"] = "Nageoires de lavande"
	L["variety.21071.mindbright.description"] = "Une lumière pâle vacille dans les lignes de ses écailles. Les pêcheurs qui en mangent disent penser plus clairement. Ils le disent souvent."
	L["variety.21071.mindbright.name"] = "Esprit-clair"
	L["variety.21071.silver-sage.description"] = "Argentée, comme des feuilles de sauge retournées par le vent."
	L["variety.21071.silver-sage.name"] = "Sauge argentée"
	L["variety.21071.sweetgrass.description"] = "Vert vif et parfumée. Le seul poisson que quiconque ait voulu ranger dans un tiroir avec le linge."
	L["variety.21071.sweetgrass.name"] = "Herbe douce"
	L["variety.21071.thyme-spotted.description"] = "De minuscules taches violettes comme des fleurs de thym. Les cuisiniers approuvent."
	L["variety.21071.thyme-spotted.name"] = "Tachée de thym"
	L["variety.21153.ashen.description"] = "Grise comme la fumée, et elle sent un peu l’encens. Plus personne ne brûle de sauge près de l’eau."
	L["variety.21153.ashen.name"] = "Cendrée"
	L["variety.21153.banded.description"] = "De larges bandes comme les cernes d’un arbre. Les vieilles en ont plus."
	L["variety.21153.banded.name"] = "Rubanée"
	L["variety.21153.bearded.description"] = "De longues nageoires traînantes comme la barbe d’un vieux sage. A l’air plus sage qu’elle ne l’est."
	L["variety.21153.bearded.name"] = "Barbue"
	L["variety.21153.bronze.description"] = "Bronze, des rivières sombres de tanin. A un léger goût de thé."
	L["variety.21153.bronze.name"] = "Bronze"
	L["variety.21153.elder-sage.description"] = "Vieille, énorme, ses écailles parcourues de lignes d’or pâle comme les nervures d’une feuille. Certains lieux gardent leurs plus vieilles choses."
	L["variety.21153.elder-sage.name"] = "Sauge ancienne"
	L["variety.21153.full-grown.description"] = "La petite a grandi : plus grande, plus sombre, toujours parfumée."
	L["variety.21153.full-grown.name"] = "Adulte"
	L["variety.21153.golden.description"] = "Dorée et parfumée. Sent le miel sur la pierre chaude."
	L["variety.21153.golden.name"] = "Dorée"
	L["variety.21153.moss-green.description"] = "Marbrée comme la mousse sur une vieille pierre. Sent la forêt humide."
	L["variety.21153.moss-green.name"] = "Vert mousse"
	L["variety.21153.silver.description"] = "Une géante argentée de son espèce. A grandi et s’est mise à briller."
	L["variety.21153.silver.name"] = "Argentée"
	L["variety.21153.violet-finned.description"] = "Des nageoires violettes, comme une sauge en fleur. Le parfum est plus fort au printemps."
	L["variety.21153.violet-finned.name"] = "Nageoires violettes"
	L["variety.251524.dreamfin.description"] = "Luit d’un rose et d’un bleu doux, et laisse un léger miroitement dans l’eau derrière lui. On dit aux petits enfants qu’il exauce les vœux. Personne ne vérifie."
	L["variety.251524.dreamfin.name"] = "Nageoire-de-rêve"
	L["variety.251524.frill-finned.description"] = "Des nageoires comme des volants de dentelle. Nul à la nage, ravi quand même."
	L["variety.251524.frill-finned.name"] = "Nageoires à volants"
	L["variety.251524.lemon.description"] = "Jaune citron à pois bleus. Il a l’air très content de quelque chose."
	L["variety.251524.lemon.name"] = "Citron"
	L["variety.251524.lilac.description"] = "Lilas rayé de crème. Nage en boucles, sans raison apparente."
	L["variety.251524.lilac.name"] = "Lilas"
	L["variety.251524.mint.description"] = "Vert menthe à pois roses. On dirait une sucrerie de foire."
	L["variety.251524.mint.name"] = "Menthe"
	L["variety.251524.murk-touched.description"] = "Violet foncé, ses pois ternis. Le seul de son espèce qui ait l’air d’avoir passé une mauvaise journée."
	L["variety.251524.murk-touched.name"] = "Assombri"
	L["variety.251524.polka-dotted.description"] = "De gros pois blancs sur du rose, comme une robe de fête. Il le sait."
	L["variety.251524.polka-dotted.name"] = "À pois"
	L["variety.251524.rainbow.description"] = "Toutes les couleurs en rayures, comme peint par un enfant avec une boîte pleine. Il scintille."
	L["variety.251524.rainbow.name"] = "Arc-en-ciel"
	L["variety.251524.swirled.description"] = "Rose et bleu mêlés en tourbillons comme un glaçage. Donne aux pêcheurs faim de la mauvaise chose."
	L["variety.251524.swirled.name"] = "Tourbillonné"
	L["variety.251524.whimsical.description"] = "Doré, aux nageoires bleues flottantes comme les écharpes d’une danseuse. On le dirait peint par quelqu’un de très bonne humeur."
	L["variety.251524.whimsical.name"] = "Fantasque"
	L["variety.4603.all-gold.description"] = "Jaune de la queue au museau. Les mouettes suivent la barque sur des lieues."
	L["variety.4603.all-gold.name"] = "Tout or"
	L["variety.4603.classic.description"] = "Dos gris-bleu, queue jaune, quelques taches sombres. L’allure que tout cuisinier de la côte attend."
	L["variety.4603.classic.name"] = "Classique"
	L["variety.4603.dusky.description"] = "Assombri par l’eau profonde, le jaune terni comme du vieux laiton."
	L["variety.4603.dusky.name"] = "Sombre"
	L["variety.4603.ghost.description"] = "Presque blanc, avec un léger reflet jaune à la queue. A l’air d’être sous l’eau même hors de l’eau."
	L["variety.4603.ghost.name"] = "Fantôme"
	L["variety.4603.gold-striped.description"] = "Une ligne jaune court du museau à la queue, comme si quelqu’un l’avait soulignée."
	L["variety.4603.gold-striped.name"] = "Rayé d’or"
	L["variety.4603.greenback.description"] = "Plus vert sur le dos, des côtes herbeuses. La queue reste fièrement jaune."
	L["variety.4603.greenback.name"] = "Dos-vert"
	L["variety.4603.leopard.description"] = "Les taches sont devenues gourmandes et se sont rejointes. Beau, dans le genre chargé."
	L["variety.4603.leopard.name"] = "Léopard"
	L["variety.4603.silverside.description"] = "Plus miroir que poisson sur les flancs. Des taches rares et timides."
	L["variety.4603.silverside.name"] = "Flanc-d’argent"
	L["variety.4603.sunset-tailed.description"] = "La queue brûle d’orange au lieu de jaune. Encore plus fier de lui, si c’était possible."
	L["variety.4603.sunset-tailed.name"] = "Queue couchante"
	L["variety.4603.tidecaller.description"] = "Un fin filet bleu luit le long de ses flancs. Les vieux marins disent que la marée tourne quand on en prend un."
	L["variety.4603.tidecaller.name"] = "Mande-marée"
	L["variety.6289.blackjaw.description"] = "La mâchoire est noire comme l’encre jusqu’aux ouïes. Il a des opinions et les partage."
	L["variety.6289.blackjaw.name"] = "Mâchoire-noire"
	L["variety.6289.brindle.description"] = "Strié comme le pelage d’un chien. Certains pêcheurs jurent qu’il grogne."
	L["variety.6289.brindle.name"] = "Bringé"
	L["variety.6289.golden.description"] = "Un lutjan doré sorti d’un étang brun. L’étang semble aussi surpris que tout le monde."
	L["variety.6289.golden.name"] = "Doré"
	L["variety.6289.lantern-eyed.description"] = "Des yeux qui accrochent la lumière comme une lampe à une fenêtre. Plus facile à trouver au crépuscule."
	L["variety.6289.lantern-eyed.name"] = "Yeux-lanternes"
	L["variety.6289.mudbank.description"] = "Brun au-dessus, fauve en dessous, la mâchoire en avant. Le lutjan que chaque étang du monde semble avoir."
	L["variety.6289.mudbank.name"] = "Banc de vase"
	L["variety.6289.old-bootbiter.description"] = "Des cicatrices d’hameçon, une nageoire déchirée et un air d’assurance totale. Chaque étang en garde un."
	L["variety.6289.old-bootbiter.name"] = "Vieux Mord-botte"
	L["variety.6289.pale.description"] = "Pâle comme le lait, rose aux nageoires. Trop joli pour la mâchoire qu’il porte."
	L["variety.6289.pale.name"] = "Pâle"
	L["variety.6289.red-clay.description"] = "Rouge rouille, des berges d’argile rouge. Même goût, plus d’allure."
	L["variety.6289.red-clay.name"] = "Argile rouge"
	L["variety.6289.reedbed.description"] = "De légères bandes vertes, à force de se cacher dans les roseaux. Mord toujours le premier."
	L["variety.6289.reedbed.name"] = "Roselière"
	L["variety.6289.speckled.description"] = "Taché de rousseur de partout, comme un garçon de ferme après la moisson."
	L["variety.6289.speckled.name"] = "Moucheté"
	L["variety.6291.blue-striped.description"] = "Une belle bande bleue sur chaque flanc, comme s’il essayait d’avoir l’air officiel."
	L["variety.6291.blue-striped.name"] = "Rayé de bleu"
	L["variety.6291.dotted.description"] = "Une rangée de petits points le long du flanc, nette comme une couture."
	L["variety.6291.dotted.name"] = "Pointillé"
	L["variety.6291.glass.description"] = "On voit sa colonne vertébrale. Il voit sans doute la vôtre."
	L["variety.6291.glass.name"] = "Verre"
	L["variety.6291.golden.description"] = "Une pièce d’or avec des nageoires. Les enfants veulent le garder. Les pêcheurs aussi."
	L["variety.6291.golden.name"] = "Doré"
	L["variety.6291.greenback.description"] = "Vert sur le dos, des eaux peu profondes et herbeuses. Deux fois plus difficile à repérer."
	L["variety.6291.greenback.name"] = "Dos-vert"
	L["variety.6291.inkfin.description"] = "Sombre comme la pointe d’une plume. Nage avec les brillants et ne trompe personne."
	L["variety.6291.inkfin.name"] = "Nageoire-d’encre"
	L["variety.6291.rainbow.description"] = "Jette des couleurs comme une bulle de savon quand il tourne. Devient gris une fois sorti de l’eau."
	L["variety.6291.rainbow.name"] = "Arc-en-ciel"
	L["variety.6291.redfin.description"] = "Des nageoires trempées dans le rouge. Se montre en banc, rarement seul."
	L["variety.6291.redfin.name"] = "Nageoire-rouge"
	L["variety.6291.silver.description"] = "Argent tout simple, qui scintille par centaines dans les hauts-fonds. Le premier poisson de bien des livres."
	L["variety.6291.silver.name"] = "Argenté"
	L["variety.6291.starlit.description"] = "De minuscules points pâles luisent le long du dos comme une nuit claire. Remarquable, pour quelque chose d’aussi petit."
	L["variety.6291.starlit.name"] = "Étoilé"
	L["variety.6299.ashen.description"] = "Gris jusqu’à l’os, comme s’il avait nagé dans la cendre. Même les mouches gardent leurs distances."
	L["variety.6299.ashen.name"] = "Cendreux"
	L["variety.6299.bilious.description"] = "Jaune-vert, comme un mauvais matin. À manipuler avec des gants."
	L["variety.6299.bilious.name"] = "Bilieux"
	L["variety.6299.blighted.description"] = "De légères veines vertes luisent sous les écailles. Certaines eaux se souviennent de ce qu’on y a déversé."
	L["variety.6299.blighted.name"] = "Flétri"
	L["variety.6299.blotchy.description"] = "Couvert de tristes taches brunes. Personne ne demande d’où elles viennent."
	L["variety.6299.blotchy.name"] = "Taché"
	L["variety.6299.bony.description"] = "Plus de côtes que de poisson. Il a fait de son mieux."
	L["variety.6299.bony.name"] = "Osseux"
	L["variety.6299.bruised.description"] = "Violet et bleu par plaques, comme s’il avait perdu une bagarre contre le courant."
	L["variety.6299.bruised.name"] = "Meurtri"
	L["variety.6299.greenish.description"] = "Des plaques de vert qui ne devraient pas être là. L’odeur arrive avant le poisson."
	L["variety.6299.greenish.name"] = "Verdâtre"
	L["variety.6299.greyish.description"] = "Gris, mou et vaguement désolé. Mauvaise mine, pire odeur."
	L["variety.6299.greyish.name"] = "Grisâtre"
	L["variety.6299.recovered.description"] = "En meilleure santé que les autres. Toujours, on ne sait comment, l’un des leurs."
	L["variety.6299.recovered.name"] = "Rétabli"
	L["variety.6299.wheezing.description"] = "Les ouïes battent d’une façon qui ressemble presque à un soupir. Il le sait."
	L["variety.6299.wheezing.name"] = "Sifflant"
	L["variety.6303.blueback.description"] = "Plus bleu, de la haute mer. Frit tout aussi bien."
	L["variety.6303.blueback.name"] = "Dos-bleu"
	L["variety.6303.bronze.description"] = "Bronze sur le dos comme une vieille pièce. Bizarre pour un maquereau. Il s’en moque."
	L["variety.6303.bronze.name"] = "Bronze"
	L["variety.6303.emerald.description"] = "Vert comme le varech, avec un miroitement qui s’efface dans l’heure."
	L["variety.6303.emerald.name"] = "Émeraude"
	L["variety.6303.golden.description"] = "Des bandes d’or sur de l’or. A l’air coûteux. Frit comme un maquereau."
	L["variety.6303.golden.name"] = "Doré"
	L["variety.6303.pearl.description"] = "Blanc comme un coquillage, les bandes réduites à leur fantôme. Ravissant, et toujours glissant."
	L["variety.6303.pearl.name"] = "Perle"
	L["variety.6303.plainback.description"] = "Aucune bande. Glisse encore plus vite entre les mains sans elles, apparemment."
	L["variety.6303.plainback.name"] = "Dos-uni"
	L["variety.6303.sea-witch.description"] = "Des bandes qui luisent vert d’eau dans le noir. Les marins les rejettent à l’eau. Puis ils le regrettent."
	L["variety.6303.sea-witch.name"] = "Sorcière des mers"
	L["variety.6303.shallow-water.description"] = "Plus pâle, des baies sableuses près du rivage. Ondule toujours."
	L["variety.6303.shallow-water.name"] = "Eau peu profonde"
	L["variety.6303.spotted.description"] = "Des points là où devraient être les bandes. Les maquereaux ne respectent pas les règles."
	L["variety.6303.spotted.name"] = "Tacheté"
	L["variety.6303.tiger-backed.description"] = "Des bandes sombres et ondulées sur un dos bleu-vert, comme des rides figées sur place."
	L["variety.6303.tiger-backed.name"] = "Dos tigré"
	L["variety.6308.albino.description"] = "Blanc aux yeux roses. N’a manifestement jamais vu le soleil, et n’en a pas l’intention."
	L["variety.6308.albino.name"] = "Albinos"
	L["variety.6308.black-barbel.description"] = "Noir d’encre des barbillons à la queue. Avale la lumière et la plupart des appâts."
	L["variety.6308.black-barbel.name"] = "Barbillon noir"
	L["variety.6308.calico.description"] = "Orange, blanc et noir par plaques, comme un chat de grange. Tout aussi peu impressionné."
	L["variety.6308.calico.name"] = "Tricolore"
	L["variety.6308.long-whiskered.description"] = "Des barbillons deux fois plus longs que d’ordinaire. A l’air sage. Ne l’est pas."
	L["variety.6308.long-whiskered.name"] = "Longs barbillons"
	L["variety.6308.marbled.description"] = "Marbré comme un lit de rivière, là justement où il passe son temps."
	L["variety.6308.marbled.name"] = "Marbré"
	L["variety.6308.mudback.description"] = "Brun vase au-dessus, crème en dessous, des barbillons partout. Le poisson-chat que chaque rivière semble garder."
	L["variety.6308.mudback.name"] = "Dos-de-vase"
	L["variety.6308.riverbed-king.description"] = "Des barbillons épais comme des cordes et une gueule comme une porte de cave. La rivière le nourrit depuis des années."
	L["variety.6308.riverbed-king.name"] = "Roi du lit de la rivière"
	L["variety.6308.slate.description"] = "Gris-bleu comme une pierre de rivière. Tout aussi têtu."
	L["variety.6308.slate.name"] = "Ardoise"
	L["variety.6308.spotted.description"] = "Des taches sombres sur les flancs, comme un jeune poisson-chat de rivière."
	L["variety.6308.spotted.name"] = "Tacheté"
	L["variety.6308.yellowbelly.description"] = "Un ventre jaune, et aucune honte. Se bat quand même."
	L["variety.6308.yellowbelly.name"] = "Ventre-jaune"
	L["variety.6317.ale-barred.description"] = "Des bandes ambrées comme une bière bien tirée. Les nains leur donnent des noms affectueux."
	L["variety.6317.ale-barred.name"] = "Rayée de bière"
	L["variety.6317.blackwater.description"] = "Noire comme le fond d’un puits de mine. Les dents sont blanches."
	L["variety.6317.blackwater.name"] = "Eau-noire"
	L["variety.6317.dam-breaker.description"] = "Des dents comme des ciseaux à bois et une mâchoire pleine de vieilles échardes. Les histoires du bord du lac commencent et finissent avec elle."
	L["variety.6317.dam-breaker.name"] = "Brise-barrage"
	L["variety.6317.ironjaw.description"] = "La mâchoire sombre comme du vieux fer, et presque aussi dure. Les gants sont conseillés."
	L["variety.6317.ironjaw.name"] = "Mâchoire-de-fer"
	L["variety.6317.peat-stained.description"] = "Brune, des eaux tourbeuses. A un léger goût de fumée."
	L["variety.6317.peat-stained.name"] = "Tachée de tourbe"
	L["variety.6317.redbelly.description"] = "Un ventre rouge comme une forge. Les dents aussi."
	L["variety.6317.redbelly.name"] = "Ventre-rouge"
	L["variety.6317.ruby.description"] = "Rouge de partout, comme une gemme sous la lampe d’un mineur. Quelqu’un essaie toujours de la vendre."
	L["variety.6317.ruby.name"] = "Rubis"
	L["variety.6317.silverflank.description"] = "Des flancs d’un argent vif, scintillants d’écailles. Toujours tout en dents."
	L["variety.6317.silverflank.name"] = "Flanc-d’argent"
	L["variety.6317.slate-backed.description"] = "Dos gris, ventre rouge, des dents. Nommée d’après sa façon de se comporter quand on la tient."
	L["variety.6317.slate-backed.name"] = "Dos d’ardoise"
	L["variety.6317.snowmelt.description"] = "Pâle, du coin le plus froid du lac. Mord tout aussi fort."
	L["variety.6317.snowmelt.name"] = "Eau de fonte"
	L["variety.6358.black-gummed.description"] = "Des gencives noires, un dos tacheté, un éclat huileux. Les alchimistes en veulent l’huile."
	L["variety.6358.black-gummed.name"] = "Gencives noires"
	L["variety.6358.bright-silver.description"] = "Tout juste sorti de la pleine eau et brillant comme une lame. L’huile est là quand même."
	L["variety.6358.bright-silver.name"] = "Argent vif"
	L["variety.6358.greenback.description"] = "Plus vert sur le dessus, des côtes à varech. Tout aussi huileux."
	L["variety.6358.greenback.name"] = "Dos-vert"
	L["variety.6358.hooknose.description"] = "Une mâchoire crochue gagnée lors de la remontée du frai. A l’air offensé en permanence."
	L["variety.6358.hooknose.name"] = "Bec-crochu"
	L["variety.6358.lampblack.description"] = "Une huile dorée suinte le long de ses écailles et luit faiblement. Les fabricants de lampes paieraient n’importe quoi. D’habitude, ils le font."
	L["variety.6358.lampblack.name"] = "Noir de lampe"
	L["variety.6358.pearl.description"] = "Blanc, avec un éclat nacré dû à toute cette huile. Plus joli que sa réputation."
	L["variety.6358.pearl.name"] = "Perle"
	L["variety.6358.rainbow-slicked.description"] = "L’huile montre toutes les couleurs au soleil. Plus joli que ce que mérite quoi que ce soit d’aussi gras."
	L["variety.6358.rainbow-slicked.name"] = "Nappe irisée"
	L["variety.6358.redflank.description"] = "Rougi le long des flancs pour le frai. Plus huileux que jamais."
	L["variety.6358.redflank.name"] = "Flanc-rouge"
	L["variety.6358.spotless.description"] = "Pas une seule tache. L’huile se charge de la décoration."
	L["variety.6358.spotless.name"] = "Sans tache"
	L["variety.6358.tar-black.description"] = "Noir de la bouche à la queue et luisant comme du goudron. Laisse une marque sur tout ce qu’il touche."
	L["variety.6358.tar-black.name"] = "Noir de goudron"
	L["variety.6359.charred.description"] = "Noir comme une bûche brûlée, les nageoires encore rougeoyantes. A l’air cuit. Ne l’est pas."
	L["variety.6359.charred.name"] = "Calciné"
	L["variety.6359.coral.description"] = "Plus rose, des eaux de récif. Un peu plus frais dans la main."
	L["variety.6359.coral.name"] = "Corail"
	L["variety.6359.deepwater.description"] = "Cramoisi sombre, des eaux profondes. Garde la chaleur plus longtemps."
	L["variety.6359.deepwater.name"] = "Eaux profondes"
	L["variety.6359.ember-spotted.description"] = "Des taches sombres comme des escarbilles sur du rouge. Sent un peu la fumée une fois sorti de l’eau."
	L["variety.6359.ember-spotted.name"] = "Taché de braise"
	L["variety.6359.flame-finned.description"] = "Un corps rouge, des nageoires comme des flammes. La couleur que la plupart des pêcheurs imaginent en entendant son nom."
	L["variety.6359.flame-finned.name"] = "Nageoires de flamme"
	L["variety.6359.flame-striped.description"] = "Des lignes jaunes y courent comme des flammes le long d’un mur."
	L["variety.6359.flame-striped.name"] = "Rayé de flammes"
	L["variety.6359.goldfin.description"] = "Des nageoires d’or au lieu de rouge. Toujours chaud."
	L["variety.6359.goldfin.name"] = "Nageoire-d’or"
	L["variety.6359.phoenix-fin.description"] = "Les nageoires brûlent d’or et le corps luit comme une forge. L’eau fume autour de lui quand on le sort."
	L["variety.6359.phoenix-fin.name"] = "Nageoire-de-phénix"
	L["variety.6359.smouldering.description"] = "Sombre comme un feu couvert, rouge sur les bords. Trop chaud pour être tenu longtemps."
	L["variety.6359.smouldering.name"] = "Couvant"
	L["variety.6359.white-flame.description"] = "Blanc, aux nageoires du rose d’une braise. La chaleur est bien réelle."
	L["variety.6359.white-flame.name"] = "Flamme blanche"
	L["variety.6361.aurora.description"] = "Les couleurs ondulent sur lui par vagues, du vert au violet, et ne s’effacent jamais. Personne ne sait expliquer pourquoi."
	L["variety.6361.aurora.name"] = "Aurore"
	L["variety.6361.barred.description"] = "Des bandes pâles sur les flancs, comme en montrent les thons quand ils se nourrissent avidement."
	L["variety.6361.barred.name"] = "Rayé"
	L["variety.6361.deep-blue.description"] = "Plus sombre, du grand large. Les nageoires gardent leurs couleurs un peu plus longtemps."
	L["variety.6361.deep-blue.name"] = "Bleu profond"
	L["variety.6361.longfin.description"] = "Des pectorales aussi longues qu’un avant-bras. Nage comme si la mer lui appartenait."
	L["variety.6361.longfin.name"] = "Longue-nageoire"
	L["variety.6361.many-hued.description"] = "Dos bleu acier, ventre argenté, nageoires de toutes les couleurs. Elles s’effacent dans l’heure, alors regardez vite."
	L["variety.6361.many-hued.name"] = "Multicolore"
	L["variety.6361.prism.description"] = "Blanc comme l’écume, chaque bande d’une couleur différente. Les garde une journée entière."
	L["variety.6361.prism.name"] = "Prisme"
	L["variety.6361.silverflank.description"] = "Plus argenté que bleu. L’arc-en-ciel ne vit que dans les nageoires."
	L["variety.6361.silverflank.name"] = "Flanc-d’argent"
	L["variety.6361.stormback.description"] = "Gris comme les nuées d’orage, les nageoires ternies en étain. Mord le mieux juste avant la pluie."
	L["variety.6361.stormback.name"] = "Dos-d’orage"
	L["variety.6361.sunset-finned.description"] = "Des nageoires orange et rose, comme un ciel à la fin d’une bonne journée de pêche."
	L["variety.6361.sunset-finned.name"] = "Nageoires couchantes"
	L["variety.6361.violet.description"] = "Un reflet violet le long du dos. Les couleurs virent à un gris boudeur une fois sorti de l’eau."
	L["variety.6361.violet.name"] = "Violet"
	L["variety.6362.barnacled.description"] = "Des balanes sur la tête, comme une vieille coque. Elle fait ça depuis longtemps, visiblement."
	L["variety.6362.barnacled.name"] = "Couverte de balanes"
	L["variety.6362.golden.description"] = "Marbrée d’or sur de l’or. On dirait une statue que quelqu’un a oublié de finir."
	L["variety.6362.golden.name"] = "Dorée"
	L["variety.6362.granite.description"] = "Mouchetée de noir et de blanc comme une meule. Pèse comme si elle en était une."
	L["variety.6362.granite.name"] = "Granit"
	L["variety.6362.harbour-grey.description"] = "Grise, des eaux du port. Tout aussi douce une fois cuite."
	L["variety.6362.harbour-grey.name"] = "Gris de port"
	L["variety.6362.kelp-green.description"] = "Vert-brun, des champs de varech. Tire plus fort qu’elle n’en a l’air."
	L["variety.6362.kelp-green.name"] = "Vert varech"
	L["variety.6362.leopard.description"] = "De grosses taches sombres sur un corps couleur de sable. Têtue, même pour une morue."
	L["variety.6362.leopard.name"] = "Léopard"
	L["variety.6362.red-rock.description"] = "Rouge rouille, des côtes de roche rouge. Les gens du coin disent que c’est un autre poisson. Ce n’en est pas un."
	L["variety.6362.red-rock.name"] = "Roche rouge"
	L["variety.6362.rock-mottled.description"] = "Marbrée de brun comme les rochers parmi lesquels elle se cache, avec une ligne pâle sur chaque flanc."
	L["variety.6362.rock-mottled.name"] = "Marbrée de roche"
	L["variety.6362.sandy.description"] = "Pâle comme une plage, finement tachetée. Rend bien dans l’assiette."
	L["variety.6362.sandy.name"] = "Sablée"
	L["variety.6362.stoneheart.description"] = "Des écailles comme de l’ardoise, une faible lueur entre elles. On la trouve là où les falaises rejoignent l’eau profonde, et nulle part ailleurs."
	L["variety.6362.stoneheart.name"] = "Cœur-de-pierre"
	L["variety.6458.black-gold.description"] = "Enduit si épais qu’il luit comme une botte cirée. Les prospecteurs y jettent un œil et se mettent à creuser."
	L["variety.6458.black-gold.name"] = "Or noir"
	L["variety.6458.half-clean.description"] = "L’huile n’en a eu que la moitié. L’autre moitié a l’air discrètement soulagée."
	L["variety.6458.half-clean.name"] = "À moitié propre"
	L["variety.6458.muddy.description"] = "Plus de boue que d’huile. Un progrès, d’une certaine façon."
	L["variety.6458.muddy.name"] = "Boueux"
	L["variety.6458.rainbow-slick.description"] = "L’huile fait des arcs-en-ciel au soleil. Un joli spectacle, et un mauvais signe."
	L["variety.6458.rainbow-slick.name"] = "Nappe arc-en-ciel"
	L["variety.6458.rust-streaked.description"] = "Des traînées de rouille venues de vieux rejets de machines. Presque un poisson."
	L["variety.6458.rust-streaked.name"] = "Strié de rouille"
	L["variety.6458.slicked.description"] = "Un petit poisson sous un manteau noir d’huile. Quelque part en amont, quelqu’un est très occupé."
	L["variety.6458.slicked.name"] = "Englué"
	L["variety.6458.somehow-clean.description"] = "Propre, brillant, en bonne santé. Il a dû arriver d’ailleurs à la nage."
	L["variety.6458.somehow-clean.name"] = "Propre, allez savoir"
	L["variety.6458.still-burning.description"] = "L’huile sur son dos couve encore, et rien ne l’éteint. À ne pas cuire à l’intérieur."
	L["variety.6458.still-burning.name"] = "Brûle encore"
	L["variety.6458.sulphur-stained.description"] = "Jaune à cause de quelque chose de pire que l’huile. En a l’odeur, aussi."
	L["variety.6458.sulphur-stained.name"] = "Taché de soufre"
	L["variety.6458.tarred.description"] = "D’épaisses plaques de goudron noir. Colle à la ligne, et au pêcheur."
	L["variety.6458.tarred.name"] = "Goudronné"
	L["variety.6522.crimson.description"] = "Rouge là où il devrait être vert. Les histoires sur l’heure qui suit sa dégustation empirent."
	L["variety.6522.crimson.name"] = "Cramoisi"
	L["variety.6522.dreamers-spawn.description"] = "Une lumière verte palpite sous ses écailles, lente comme un souffle endormi. Le cauchemar des cavernes a laissé sa marque ici."
	L["variety.6522.dreamers-spawn.name"] = "Rejeton du rêveur"
	L["variety.6522.glowgill.description"] = "Des ouïes qui luisent faiblement de vert. Ça se lit comme un avertissement, et c’en est un."
	L["variety.6522.glowgill.name"] = "Ouïes-lueur"
	L["variety.6522.lizard-scaled.description"] = "Des écailles comme la peau d’un raptor. Moitié poisson, moitié quelque chose qui a des opinions."
	L["variety.6522.lizard-scaled.name"] = "Écailles de lézard"
	L["variety.6522.many-eyed.description"] = "Des ocelles tout le long des flancs. Au moins deux clignent."
	L["variety.6522.many-eyed.name"] = "Mille-yeux"
	L["variety.6522.misshapen.description"] = "Vert, bosselé et anormal à plusieurs endroits à la fois. À manger à vos risques et périls."
	L["variety.6522.misshapen.name"] = "Difforme"
	L["variety.6522.pale-nightmare.description"] = "Pâle comme un spectre, les organes vaguement visibles. A l’allure d’un mauvais rêve en plein midi."
	L["variety.6522.pale-nightmare.name"] = "Cauchemar pâle"
	L["variety.6522.purple-finned.description"] = "Des nageoires violet ecchymose. Personne ne s’accorde à dire si c’est mieux ou pire."
	L["variety.6522.purple-finned.name"] = "Nageoires pourpres"
	L["variety.6522.spined.description"] = "Une crête d’épines le long du dos, qui n’était pas là hier."
	L["variety.6522.spined.name"] = "Épineux"
	L["variety.6522.two-tailed.description"] = "Deux queues, et il nage comme s’il se disputait avec lui-même pour savoir laquelle utiliser."
	L["variety.6522.two-tailed.name"] = "Deux-queues"
	L["variety.8365.bright-headed.description"] = "Corps olive, flancs tachetés, une tête qui brille comme du métal poli. La truite habituelle des rivières chaudes."
	L["variety.8365.bright-headed.name"] = "Tête brillante"
	L["variety.8365.brook-spotted.description"] = "Des taches pâles sur de l’olive, des ruisseaux froids et vifs."
	L["variety.8365.brook-spotted.name"] = "Tachetée de ruisseau"
	L["variety.8365.golden.description"] = "Dorée de partout, comme la rare truite des lacs de haute montagne."
	L["variety.8365.golden.name"] = "Dorée"
	L["variety.8365.goldhead.description"] = "De l’or là où l’éclat devrait être d’argent. Le forgeron demande deux fois."
	L["variety.8365.goldhead.name"] = "Tête-d’or"
	L["variety.8365.ironhead.description"] = "Sombre de partout, la tête comme de la fonte. Tout aussi dure à cuire."
	L["variety.8365.ironhead.name"] = "Tête-de-fer"
	L["variety.8365.parr-marked.description"] = "Des marques en empreintes de pouce sur les flancs, comme en portent les jeunes truites. Une fleur tardive."
	L["variety.8365.parr-marked.name"] = "Marques de tacon"
	L["variety.8365.quicksilver.description"] = "Argentée du museau à la queue, avec un éclat bleu pâle. Le forgeron tient enfin son affaire."
	L["variety.8365.quicksilver.name"] = "Vif-argent"
	L["variety.8365.rainbow-banded.description"] = "Une bande rose sur le flanc, comme en porte la truite arc-en-ciel."
	L["variety.8365.rainbow-banded.name"] = "Bande arc-en-ciel"
	L["variety.8365.red-spotted.description"] = "Des taches rouges cerclées de bleu. Assez jolie pour faire hésiter un pêcheur avant la poêle."
	L["variety.8365.red-spotted.name"] = "Tachetée de rouge"
	L["variety.8365.steelhead.description"] = "Gris-bleu et brillante, des grandes eaux. Tire comme si elle le pensait vraiment."
	L["variety.8365.steelhead.name"] = "Tête-d’acier"
end)
